// cases: [mã ca, khoa, ngày gặp, đáng đào sâu 0/1, id trang Notion, tình trạng, cờ 6 phần phân tích, {d: chẩn đoán, c: chuyên đề [[tên,id]], s: nội dung các toggle}]
window.BENH_PHONG = {
  generatedAt: "2026-09-30T07:10:33.573Z",
  cases: [
    ["NG-001","Ngoại khoa","2026-09-29",1,"3eacb1425c81818abd36cf1b1c62c254","Đang nằm viện","111110",{"d":"Sỏi mật khác (ICD-10 K80.8, theo mã trong bệnh án). Chưa có chẩn đoán lâm sàng đầy đủ. Kèm tổn thương thận cấp, giảm tiểu cầu nặng, thiếu máu.","c":[["Viêm đường mật cấp nặng (TG18 độ III): tiêu chuẩn suy cơ quan và thời điểm dẫn lưu","3eacb1425c8181fbac46c13dad58d1c0"],["Rối loạn kiềm toan hỗn hợp và tương tác K–Na–Ca khi truyền bicarbonate trong AKI","3eacb1425c81819ab22fdb5e52c7b104"]],"s":{"CLS":[{"k":"t","h":true,"r":[["Chỉ số","Tham chiếu","28/09","29/09"],["Creatinine (µmol/L)","62–115 (nam), 53–97 (nữ)","420","570"],["Tiểu cầu (G/L)","150–400","–","33"],["Na+ (mmol/L)","135–145","–","129,7"],["K+ (mmol/L)","3,5–5,0","–","2,86"],["Ca2+ (mmol/L)","1,15–1,35","–","1,07"],["Cl- (mmol/L)","98–107","–","101,7"],["pH","7,35–7,45","–","7,396"],["pCO2 (mmHg)","35–45","–","30,8"],["pO2 (mmHg)","80–100","–","119,5"],["sO2 (%)","95–100","–","98,5"],["HCO3- chuẩn (mmol/L)","22–26","–","18,5"],["BE (mmol/L)","-2 đến +2","–","-5,7"],["BEecf (mmol/L)","-2 đến +2","–","-6,3"],["BB (mmol/L)","–","–","39,28"],["Hct (%)","40–50 (nam), 36–46 (nữ)","–","22,8"],["Hb (g/dL)","13–17 (nam), 12–16 (nữ)","–","7,8"],["Baro (mmHg)","–","–","758"]]},{"k":"p","x":"Khí máu động mạch + điện giải lấy 29/09 (FiO2 21%). Màu: **xanh = thấp hơn tham chiếu, đỏ = cao hơn, đen = bình thường.** Cột tham chiếu tạm dùng khoảng người lớn thường dùng, sẽ thay bằng bảng của phòng xét nghiệm khi có.","d":0},{"k":"p","x":"**Đã chỉ định 29/09 (chưa có kết quả):**","d":0},{"k":"b","x":"PT/tỷ lệ prothrombin","d":0},{"k":"b","x":"APTT","d":0},{"k":"b","x":"Fibrinogen","d":0},{"k":"b","x":"Bilirubin TT và TP","d":0},{"k":"b","x":"ALP, ALT, AST","d":0},{"k":"b","x":"Creatinin, calci","d":0},{"k":"b","x":"Nhóm máu ABO Rh(D)","d":0},{"k":"b","x":"Tổng phân tích tế bào máu","d":0},{"k":"b","x":"Khí máu","d":0}],"Điều trị":[{"k":"p","x":"**28/09 (23:05):**","d":0},{"k":"b","x":"Natri clorid 0,9% 500 mL x 1 chai","d":0},{"k":"b","x":"Clindamycin 600 mg x 1 ống pha NaCl 0,9% 100 mL","d":0},{"k":"p","x":"**29/09 (08:00):**","d":0},{"k":"b","x":"Natri bicarbonat 1,4% (3,5 g/250 mL) x 1 chai","d":0},{"k":"b","x":"Natri clorid 0,9% 500 mL x 2 chai","d":0},{"k":"b","x":"Tenafotin 2000 (2 g) x 2 lọ (08:00 và 16:00)","d":0},{"k":"b","x":"Rabeloc I.V. 20 mg x 2 lọ (08:00 và 16:00)","d":0},{"k":"b","x":"Vinzix 20 mg/2 mL x 1 ống (08:00)","d":0},{"k":"b","x":"Spirovell 50 mg x 1 viên (08:00 và 16:00)","d":0},{"k":"b","x":"Nước cất pha tiêm 5 mL x 2 ống","d":0}],"Phân tích đề nghị CLS (AI)":[{"k":"p","x":"⚠ Chưa có bệnh sử và khám lâm sàng nên phân tích chỉ dựa trên số liệu CLS.","d":0},{"k":"p","x":"**1. ĐÃ CÓ VÀ Ý NGHĨA**","d":0},{"k":"b","x":"Creatinine 420 → 570 µmol/L trong khoảng 24h (4,75 → 6,45 mg/dL; +150 µmol/L, +36%): AKI đang tiến triển. Đạt ngưỡng KDIGO giai đoạn 3 (≥ 353,6 µmol/L) nếu xác nhận là tổn thương cấp; chưa biết creatinine nền.","d":0},{"k":"b","x":"Tiểu cầu 33 G/L: giảm tiểu cầu nặng (< 50). Hb 7,8 g/dL: thiếu máu (Hb/Hct của máy khí máu chỉ tham khảo, chờ công thức máu).","d":0},{"k":"b","x":"Khí máu (FiO2 21%, Baro 758): pH 7,396 | pCO2 30,8 | HCO3 chuẩn 18,5. HCO3 thực tự tính (Henderson–Hasselbalch) ≈ 18,7. Toan chuyển hoá bù trừ. Winter: pCO2 dự kiến = 1,5×18,7 + 8 ≈ 36 ± 2, đo được 30,8 thấp hơn → gợi ý kèm kiềm hô hấp (tăng thông khí do nhiễm khuẩn, đau, thiếu máu).","d":0},{"k":"b","x":"AG = 129,7 − (101,7 + 18,7) ≈ 9,3: bình thường, nhưng chưa có albumin. Albumin thấp làm AG bị che, cần hiệu chỉnh (mỗi 1 g/dL albumin giảm thì AG thật cao hơn khoảng 2,5).","d":0},{"k":"b","x":"PaO2 119,5 với FiO2 0,21: PaO2/FiO2 ≈ 569, chưa suy hô hấp. PAO2 tự tính ≈ 111, không có bằng chứng gradient A–a bất thường.","d":0},{"k":"b","x":"Na 129,7 (hạ), K 2,86 (hạ), Ca ion 1,07 (hạ).","d":0},{"k":"b","x":"Bộ xét nghiệm 29/09 (PT, APTT, fibrinogen, bilirubin, ALP, AST, ALT, nhóm máu, công thức máu, calci): hợp lý để tìm ứ mật, rối loạn đông máu (DIC?) và chuẩn bị thủ thuật/truyền máu.","d":0},{"k":"p","x":"**2. NÊN CÂN NHẮC THÊM (nếu phù hợp lâm sàng)**","d":0},{"k":"b","x":"Ngay: lactate, albumin, INR, CRP/procalcitonin, cấy máu, D-dimer (tính điểm DIC theo ISTH), lipase/amylase (sỏi mật + hạ Ca ion → loại viêm tụy cấp do sỏi), Mg, ECG (K thấp + Ca thấp).","d":0},{"k":"b","x":"Phết máu ngoại vi tìm mảnh vỡ hồng cầu, LDH, haptoglobin (loại vi mạch huyết khối/tan máu). Loại trừ giảm tiểu cầu giả do kết tụ EDTA.","d":0},{"k":"b","x":"Nước tiểu: lượng nước tiểu/giờ, Na niệu, FeNa hoặc FeUrea, cặn nước tiểu, đạm niệu.","d":0},{"k":"b","x":"Hình ảnh: siêu âm bụng (đường mật, thận, loại tắc nghẽn sau thận). MRCP không tiêm thuốc là lựa chọn hợp lý khi eGFR rất thấp; CT có cản quang cần cân nhắc lợi/hại vì AKI.","d":0},{"k":"p","x":"**3. CHƯA ƯU TIÊN:** CT cản quang khi siêu âm/MRCP đã đủ trả lời; lặp lại khí máu thường quy nếu ổn định.","d":0}],"Phân tích điều trị (AI)":[{"k":"p","x":"⚠ Chưa biết chẩn đoán xác định, cân nặng, nước tiểu, sinh hiệu, nên chỉ nhận xét theo y lệnh đã cho. Thuốc gọi theo tên thương mại được đánh dấu \"cần đối chiếu nhãn\".","d":0},{"k":"p","x":"**KHÁNG SINH**","d":0},{"k":"b","x":"Clindamycin 600 mg (28/09) + Tenafotin 2 g x 2 lần/ngày (29/09; nhiều khả năng là cefoxitin, cần đối chiếu nhãn).","d":0},{"k":"b","x":"Clindamycin không phủ trực khuẩn Gram âm đường ruột nên không đủ một mình cho nhiễm khuẩn đường mật. Cefoxitin đã phủ kỵ khí nên clindamycin có thể trùng phổ.","d":0},{"k":"b","x":"Nếu là viêm đường mật cấp độ III (Tokyo Guidelines 2018), phác đồ thường ưu tiên piperacillin/tazobactam, cefepime hoặc ceftazidime ± metronidazole, hoặc carbapenem (cần đối chiếu bảng kháng sinh TG18 và kháng sinh đồ tại chỗ). Cefoxitin thường xếp cho mức độ nhẹ hơn.","d":0},{"k":"b","x":"Creatinine 570 µmol/L: hầu hết β-lactam cần chỉnh liều theo độ thanh thải creatinine; liều 2 g x 2–3 lần/ngày có thể quá cao, cần đối chiếu.","d":0},{"k":"b","x":"Cấy máu nên lấy trước liều tiếp theo, điều chỉnh theo kết quả.","d":0},{"k":"p","x":"**DỊCH VÀ ĐIỆN GIẢI**","d":0},{"k":"b","x":"NaCl 0,9%: hợp lý để hồi sức nếu thiếu thể tích, nhưng cần đánh giá thể tích trước (hạ Na 129,7 có thể do mất dịch hoặc do quá tải dịch). Na chỉ nên tăng ≤ 8–10 mmol/L/24h; bù K cũng làm Na huyết thanh tăng.","d":0},{"k":"b","x":"Natri bicarbonat 1,4% 250 mL: pH 7,396 (không toan máu) nên chỉ định yếu. BICAR-ICU (Jaber, Lancet 2018) chỉ thấy lợi ích ở pH ≤ 7,20 kèm AKI. Nguy cơ: đẩy K vào tế bào (K đang 2,86) và giảm Ca ion (đang 1,07) → loạn nhịp, co giật. Cần đối chiếu mục đích y lệnh.","d":0},{"k":"b","x":"Chưa thấy y lệnh bù K/Ca. K cần bù từng bước, kiểm tra lại sau mỗi lần vì AKI làm giảm thải K.","d":0},{"k":"p","x":"**LỢI TIỂU**","d":0},{"k":"b","x":"Vinzix 20 mg/2 mL (furosemide) 1 ống lúc 08:00: lợi tiểu quai không cải thiện hồi phục thận trong AKI, chỉ dùng khi quá tải dịch. Làm nặng thêm hạ Na, hạ K và mất thể tích nếu bệnh nhân đang thiếu dịch.","d":0},{"k":"b","x":"Spirovell 50 mg: chưa xác định chắc hoạt chất (có thể là spironolactone, cần đối chiếu nhãn). Nếu đúng: kháng aldosterone gây tăng K nguy hiểm khi AKI nặng, dù K hiện thấp. Nên hỏi lại chỉ định (cổ trướng? suy tim?).","d":0},{"k":"p","x":"**ỨC CHẾ BƠM PROTON**","d":0},{"k":"b","x":"Rabeloc I.V. 20 mg x 2/ngày (nhiều khả năng rabeprazole tĩnh mạch, cần đối chiếu nhãn): hợp lý nếu dự phòng xuất huyết tiêu hoá do stress (giảm tiểu cầu nặng, rối loạn đông máu, nhiễm khuẩn huyết là yếu tố nguy cơ).","d":0},{"k":"p","x":"**CÒN THIẾU TRONG HỒ SƠ**","d":0},{"k":"b","x":"Dẫn lưu/giải áp đường mật (ERCP hay PTBD): với viêm đường mật nặng, TG18 khuyến cáo dẫn lưu khẩn ngay sau hồi sức. Khi tiểu cầu 33 G/L và đông máu chưa có kết quả, cân nhắc đặt stent nhựa không cắt cơ vòng để giảm chảy máu. Ngưỡng tiểu cầu thường dùng ≥ 50 G/L cho thủ thuật nguy cơ chảy máu cao (cần đối chiếu quy định tại chỗ).","d":0},{"k":"b","x":"Theo dõi nước tiểu/giờ; truyền máu/tiểu cầu/huyết tương theo kết quả đông máu; cân nhắc lọc máu nếu toan/tăng K/quá tải dịch/vô niệu tiến triển.","d":0}],"Thắc mắc lâm sàng":[{"k":"n","x":"Chẩn đoán thật sự là gì? K80.8 chỉ là mã ICD. Bệnh nhân có sốt, vàng da, đau hạ sườn phải (tam chứng Charcot)? Viêm đường mật, viêm túi mật, hay viêm tụy cấp do sỏi?","d":0},{"k":"n","x":"AKI: creatinine nền là bao nhiêu? Nước tiểu bao nhiêu mL/giờ? Nguyên nhân trước thận (thiếu dịch), hoại tử ống thận cấp (nhiễm khuẩn huyết), bệnh thận do ứ mật, hội chứng gan thận, hay tắc nghẽn sau thận?","d":0},{"k":"n","x":"Tiểu cầu 33 G/L do đâu: DIC do nhiễm khuẩn huyết, vi mạch huyết khối (HUS/TTP), cường lách (xơ gan?), thuốc, hay kết tụ EDTA? Phết máu và điểm ISTH nói gì?","d":0},{"k":"n","x":"Vì sao cùng lúc hạ Na, hạ K và toan chuyển hoá? Mất qua đường nào (nôn, tiêu chảy, dẫn lưu mật/tụy) hay do thuốc (lợi tiểu)? Có dẫn lưu nào đang chảy không?","d":0},{"k":"n","x":"Y lệnh: vì sao bù bicarbonate khi pH 7,396? Vì sao lợi tiểu và kháng aldosterone khi K thấp, Na thấp, AKI? Kháng sinh đã đủ phổ và chỉnh liều theo eGFR chưa?","d":0},{"k":"n","x":"Khi nào và bằng cách nào dẫn lưu đường mật (ERCP hay PTBD hay mổ) khi tiểu cầu 33 G/L và đông máu chưa có kết quả? Truyền tiểu cầu ở ngưỡng nào?","d":0}],"Kiến thức cần nắm":[{"k":"p","x":"**1. CHẨN ĐOÁN VIÊM ĐƯỜNG MẬT CẤP (TG18)**","d":0},{"k":"b","x":"A. Viêm toàn thân: sốt/ớn lạnh, bạch cầu bất thường hoặc CRP tăng.","d":0},{"k":"b","x":"B. Ứ mật: vàng da (bilirubin TP ≥ 2 mg/dL ≈ 34 µmol/L), xét nghiệm gan bất thường (ALP, GGT, AST, ALT > 1,5 x giới hạn trên).","d":0},{"k":"b","x":"C. Hình ảnh: giãn đường mật, hoặc thấy nguyên nhân (sỏi, hẹp, stent).","d":0},{"k":"b","x":"Nghi ngờ: 1 mục A + 1 mục B hoặc C. Xác định: đủ A + B + C.","d":0},{"k":"p","x":"**2. PHÂN ĐỘ III (nặng): có ≥ 1 rối loạn chức năng cơ quan**","d":0},{"k":"b","x":"Tim mạch (cần vận mạch), thần kinh (rối loạn ý thức), hô hấp (PaO2/FiO2 < 300), thận (thiểu niệu hoặc creatinine > 2,0 mg/dL), gan (INR > 1,5), huyết học (tiểu cầu < 100 G/L).","d":0},{"k":"b","x":"Ca này: thận đạt (creatinine 4,75–6,45 mg/dL), huyết học đạt (33 G/L), hô hấp chưa đạt (≈ 569), INR đang chờ. Nếu xác định là viêm đường mật thì thuộc độ III (bẫy: cần chẩn đoán trước rồi mới phân độ).","d":0},{"k":"p","x":"**3. KDIGO AKI**","d":0},{"k":"b","x":"Tiêu chuẩn: creatinine tăng ≥ 26,5 µmol/L trong 48h, hoặc ≥ 1,5 lần nền trong 7 ngày, hoặc nước tiểu < 0,5 mL/kg/giờ trong ≥ 6h.","d":0},{"k":"b","x":"Giai đoạn 3: ≥ 3 lần nền, hoặc creatinine ≥ 353,6 µmol/L (4,0 mg/dL), hoặc cần lọc máu.","d":0},{"k":"p","x":"**4. ĐỌC KHÍ MÁU 4 BƯỚC**","d":0},{"k":"b","x":"pH → HCO3/pCO2 xác định rối loạn chính → kiểm tra bù trừ (Winter cho toan chuyển hoá: pCO2 = 1,5 x HCO3 + 8 ± 2) → tính AG (hiệu chỉnh albumin).","d":0},{"k":"b","x":"Bẫy: HCO3 \"chuẩn\" khác HCO3 thực; Hb/Hct khí máu không thay công thức máu.","d":0},{"k":"p","x":"**5. BẪY ĐIỆN GIẢI**","d":0},{"k":"b","x":"Bicarbonate làm K và Ca ion giảm thêm.","d":0},{"k":"b","x":"Bù K làm Na tăng, chú ý hạ Na mạn tính (tốc độ tăng ≤ 8–10 mmol/L/24h).","d":0},{"k":"b","x":"Bù K trong AKI phải từng bước.","d":0},{"k":"p","x":"**6. Giảm tiểu cầu giả do kết tụ EDTA:** kiểm tra phết máu, lấy lại mẫu ống citrate.","d":0}],"Kiến thức cần đào sâu":[{"k":"p","x":"**1. VIÊM ĐƯỜNG MẬT CẤP NẶNG: cơ chế và thời điểm dẫn lưu**","d":0},{"k":"b","x":"Áp lực trong đường mật tăng → trào ngược vi khuẩn và nội độc tố vào tĩnh mạch gan/bạch mạch (cholangiovenous reflux) → nhiễm khuẩn huyết. Đó là lý do dẫn lưu quan trọng hơn kháng sinh.","d":0},{"k":"b","x":"Chọn ERCP hay PTBD; stent nhựa không cắt cơ vòng khi rối loạn đông máu. Nguồn: Tokyo Guidelines 2018 (Miura, Kiriyama và cs.).","d":0},{"k":"p","x":"**2. AKI TRONG NHIỄM KHUẨN VÀ Ứ MẬT**","d":0},{"k":"b","x":"Hoại tử ống thận cấp, bệnh thận do ứ mật (cholemic nephropathy), hội chứng gan thận, tắc nghẽn: phân biệt bằng nước tiểu, FeNa/FeUrea, cặn nước tiểu, siêu âm. Nguồn: KDIGO AKI 2012, Harrison.","d":0},{"k":"p","x":"**3. RỐI LOẠN KIỀM TOAN HỖN HỢP VÀ TƯƠNG TÁC K–Na–Ca**","d":0},{"k":"b","x":"Hạ K + hạ Na + hạ Ca ion + toan chuyển hoá: mất qua đường tiêu hoá/dẫn lưu, lợi tiểu, hay bệnh thận. Vì sao bicarbonate và bù K làm đổi Na, Ca ion. Nguồn: Harrison, UpToDate (acid-base, hyponatremia). RCT: BICAR-ICU (Jaber, Lancet 2018).","d":0},{"k":"p","x":"**4. GIẢM TIỂU CẦU NẶNG TRONG NHIỄM KHUẨN**","d":0},{"k":"b","x":"DIC (điểm ISTH) so với vi mạch huyết khối (HUS/TTP); ngưỡng truyền tiểu cầu cho thủ thuật. Nguồn: ISTH DIC guidance, hướng dẫn truyền tiểu cầu (AABB, BSH).","d":0}]}}],
    ["MH001","Ngoại khoa","2026-09-28",1,"3ebcb1425c818154bfe4ff249f9ce775","Đang nằm viện","111110",{"d":"Đau hố chậu phải, thành manh tràng phù nề trên CT: theo dõi viêm ruột thừa hoặc viêm hồi-manh tràng, chưa loại trừ u manh tràng (C18.0); chờ nội soi đại tràng","c":[["Đau hố chậu phải ở người trên 60 tuổi: viêm ruột thừa hay u manh tràng — tiếp cận chẩn đoán, chỉ định mổ và thời điểm nội soi","3ebcb1425c818124b1cdd5fe4daffd0a"]],"s":{"CLS":[{"k":"t","h":true,"r":[["Chỉ số","Tham chiếu","28/09","29/09"],["Bạch cầu WBC (G/L)","4–11","11.6","–"],["NEUT (%)","45–75","75.0","–"],["NEUT (G/L)","1.8–8.25","8.7","–"],["LYM (%)","20–40","14.2","–"],["LYM (G/L)","0.8–4.4","1.6","–"],["MONO (%)","4.0–10.0","9.7","–"],["MONO (G/L)","0.16–1.1","1.1","–"],["EOS (%)","2.0–8.0","0.8","–"],["EOS (G/L)","0.08–0.88","0.1","–"],["BASO (%)","0.0–2.0","0.3","–"],["BASO (G/L)","0.0–0.22","0.0","–"],["Hồng cầu RBC (T/L)","3.8–5.5","4.48","–"],["Hemoglobin (g/L)","120–170","139","–"],["Hematocrit (%)","34–50","41.7","–"],["MCV (fL)","78–100","93.2","–"],["MCH (pg)","24–33","31.0","–"],["MCHC (g/L)","315–355","333","–"],["RDW-CV (%)","11–16","12.7","–"],["RDW-SD (fL)","37–54","42.4","–"],["Tiểu cầu PLT (G/L)","150–450","238","–"],["MPV (fL)","7.0–12","8.0","–"],["PCT tiểu cầu (%)","0.1–0.5","0.190","–"],["CRP","<10","–","84.90"],["Glucose (mmol/L)","3.9–6.4","5.35","–"],["Ure máu (mmol/L)","1.7–8.3","4.66","–"],["Creatinin (µmol/L)","Nam 59–104","79.3","–"],["Natri (mmol/L)","135–145","136.8","–"],["Kali (mmol/L)","3.5–5.0","3.88","–"],["Chloride (mmol/L)","96–110","102.0","–"],["AST / SGOT (U/L)","Nam 10–50","22.8","–"],["ALT / SGPT (U/L)","Nam 10–50","12.3","–"],["Bilirubin toàn phần (µmol/L)","<17.1","–","7.3"],["Bilirubin trực tiếp (µmol/L)","<5.1","–","1.9"],["Albumin (g/L)","35–52","–","38.3"],["Prealbumin (µmol/L)","3.64–7.28","–","3.4"],["CEA (ng/mL)","Không hút thuốc: < (con số bị cắt khỏi ảnh)","–","4.51"],["PT (giây)","10–13","–","12.0"],["INR","1–1.2","–","1.06"],["PT (%)",">70","–","92"],["APTT (giây)","25.6–38.4","–","27.0"],["APTT tỷ lệ (ratio)","0.8–1.2","–","0.87"],["Fibrinogen (g/L)","2.0–4.0","–","4.39"],["Nhóm máu ABO, Rh(D)","–","–","B, Rh(D) dương"]]},{"k":"p","x":"Màu: xanh = thấp hơn tham chiếu, đỏ = cao hơn, đen = bình thường.","d":0},{"k":"p","x":"**Ghi chú về bảng:**","d":0},{"k":"b","x":"Tham chiếu lấy từ cột “Phạm vi” hoặc “Trị số bình thường” trên phần mềm xét nghiệm trong ảnh.","d":0},{"k":"b","x":"Xét nghiệm 28/09 thực hiện lúc 10:40 (chỉ định 09:20). Albumin, bilirubin, CEA, prealbumin thực hiện 29/09 lúc 14:00. PT, APTT, fibrinogen, CRP và nhóm máu chỉ định 29/09 lúc 08:05, giờ trả kết quả không hiện trong ảnh nên xếp vào cột 29/09.","d":0},{"k":"b","x":"CEA: ô tham chiếu bị cắt khỏi ảnh (chỉ thấy “Không hút thuốc: <”), nên chưa tô màu.","d":0},{"k":"b","x":"Đơn vị của công thức máu (trừ những dòng có ghi) và của CRP không hiện trong ảnh; ghi theo đơn vị thường dùng. “PCT” trong công thức máu là plateletcrit (thể tích tiểu cầu), không phải procalcitonin.","d":0},{"k":"b","x":"Bảng công thức máu trong ảnh có 22 dòng; nếu còn dòng khác thì đã bị cuộn khỏi khung.","d":0},{"k":"p","x":"**Chẩn đoán hình ảnh:**","d":0},{"k":"b","x":"**Siêu âm ổ bụng 28/09/2026 (khoa Cấp cứu):**","d":0},{"k":"b","x":"Gan: không lớn, bờ đều, đồng nhất, không có tổn thương khu trú.","d":1},{"k":"b","x":"Mật: túi mật không sỏi, không dãn; đường mật không sỏi, không dãn.","d":1},{"k":"b","x":"Lách không lớn, đồng dạng. Tuỵ bình thường. Hai thận không sỏi, không ứ nước, chủ mô bình thường. Bàng quang thành không dày, không cặn lắng, không sỏi. Màng phổi không dịch. Dịch ổ bụng (-).","d":1},{"k":"b","x":"Hồi-manh tràng: thành dày, giảm âm.","d":1},{"k":"b","x":"Vùng hố chậu phải: vài hạch giảm âm, đường kính lớn nhất khoảng 10 mm. Ruột thừa nghi nằm sau manh tràng, đường kính khoảng 6 mm, có thâm nhiễm viêm.","d":1},{"k":"b","x":"Kết luận: theo dõi viêm ruột thừa sau manh tràng; viêm hồi-manh tràng; theo dõi hạch phản ứng vùng hố chậu phải.","d":1},{"k":"b","x":"**CT có cản quang (ghi “CLVT có thuốc”, Omnipaque 300 mg/mL x 50 mL tiêm tĩnh mạch; vùng chụp, ngày giờ không hiện trong ảnh; phiếu in trên mẫu phiếu siêu âm chẩn đoán):**","d":0},{"k":"b","x":"Gan không lớn, bờ đều, đồng nhất, không thấy khối khu trú. Đường mật không dãn, không sỏi. Túi mật không sỏi, thành không dày.","d":1},{"k":"b","x":"Lách không lớn, không thấy khối khu trú. Tuỵ đồng nhất, không thấy khối, ống tuỵ không dãn.","d":1},{"k":"b","x":"Thận phải: vài sỏi, đường kính lớn nhất khoảng 3 mm, đài bể thận không dãn. Niệu quản không dãn, không sỏi. Thận trái: không thấy sỏi, đài bể thận không dãn, niệu quản không dãn, không sỏi. Bàng quang không sỏi, thành không dày.","d":1},{"k":"b","x":"Tạng rỗng: ruột thừa chưa thấy viêm. Manh tràng thành phù nề, thâm nhiễm mỡ xung quanh.","d":1},{"k":"b","x":"Không thấy hạch lớn trong ổ bụng. Không thấy dịch, khí tự do ổ bụng.","d":1},{"k":"b","x":"Kết luận: theo dõi viêm manh tràng (phân biệt: theo dõi u manh tràng) và sỏi thận phải. Đề nghị kết hợp thêm nội soi.","d":1},{"k":"b","x":"**Nhận xét dữ kiện:** siêu âm nghi viêm ruột thừa sau manh tràng (khoảng 6 mm, thâm nhiễm viêm), còn CT ghi ruột thừa chưa thấy viêm; cả hai cùng thấy thành hồi-manh tràng hoặc manh tràng dày, phù nề.","d":0},{"k":"p","x":"**CLS đã có kế hoạch hoặc chưa thấy trong ảnh:**","d":0},{"k":"b","x":"Nội soi dạ dày và nội soi đại tràng: đang chờ (y lệnh 30/09).","d":0},{"k":"b","x":"Giải phẫu bệnh: chưa có.","d":0},{"k":"b","x":"Điện tâm đồ, X-quang ngực, tổng phân tích nước tiểu: không thấy trong ảnh.","d":0},{"k":"b","x":"Công thức máu, CRP lặp sau 29/09: chưa thấy.","d":0}],"Điều trị":[{"k":"p","x":"**28/09 (16:00):**","d":0},{"k":"b","x":"Clindamycin (Clindamycin-Hameln 150 mg/mL, hàm lượng ghi 600 mg): 1 ống, truyền tĩnh mạch pha muối","d":0},{"k":"b","x":"Natri clorid 0,9% (100 mL): 1 chai, truyền tĩnh mạch pha kháng sinh","d":0},{"k":"p","x":"**29/09 (08:00):**","d":0},{"k":"b","x":"Clindamycin 600 mg: 2 ống, truyền tĩnh mạch 08:00 - 16:00 (ghi “(2)” = ngày dùng thứ 2)","d":0},{"k":"b","x":"Các y lệnh còn lại của phiếu 29/09 bị cắt khỏi ảnh","d":0},{"k":"p","x":"**30/09 (07:42):**","d":0},{"k":"b","x":"Clindamycin 600 mg: 2 ống, truyền tĩnh mạch 08:00 - 16:00 (ghi “(3)” = ngày dùng thứ 3)","d":0},{"k":"b","x":"Natri clorid 0,9% (100 mL): 2 chai, truyền tĩnh mạch pha thuốc","d":0},{"k":"b","x":"Cephalothin 2000 mg (tên thương mại đọc chưa chắc, giống “Thimmcz-2000”; hoạt chất ghi trên phiếu là cephalothin natri): 2 lọ, tiêm tĩnh mạch 08:00 - 16:00 (ghi “(2)” = ngày dùng thứ 2, tức bắt đầu khoảng 29/09)","d":0},{"k":"b","x":"Nước cất pha tiêm 5 mL: 4 ống, tiêm tĩnh mạch (2 lần pha thuốc)","d":0},{"k":"b","x":"Naprozole-R 20 mg: 2 lọ, tiêm tĩnh mạch 08:00 - 16:00","d":0},{"k":"b","x":"Biosubtyl-II (chế phẩm men vi sinh 10 mũ 7 - 10 mũ 8 CFU): 3 viên, uống 08:00 - 14:00 - 20:00","d":0},{"k":"p","x":"**Y lệnh chăm sóc và theo dõi:**","d":0},{"k":"b","x":"Theo dõi mạch, nhiệt, huyết áp: 12 giờ/lần (28/09); 6 giờ/lần (30/09)","d":0},{"k":"b","x":"Chăm sóc: cấp ba (28/09); cấp hai (30/09)","d":0},{"k":"b","x":"Dinh dưỡng: BT02-Cơm (28/09); BT01-Cơm (30/09)","d":0},{"k":"p","x":"**Chưa thấy trong y lệnh đọc được:** thuốc giảm đau hoặc hạ sốt, dịch duy trì, dự phòng huyết khối.","d":0}],"Phân tích đề nghị CLS (AI)":[{"k":"p","x":"**Khung tiếp cận của khoa Ngoại (3 câu hỏi, theo thứ tự)**","d":0},{"k":"b","x":"Câu 1: đã đủ chẩn đoán và chỉ định mổ chưa?","d":0},{"k":"b","x":"Câu 2: nếu có chỉ định mổ, bệnh nhân có chịu đựng được cuộc mổ không (đông máu, đường huyết, thận, tim phổi, dinh dưỡng)?","d":0},{"k":"b","x":"Câu 3: sau mổ, CLS chỉ định theo diễn tiến có phù hợp thực tế của bệnh nhân không?","d":0},{"k":"p","x":"**CÂU 1. Đã đủ chẩn đoán và chỉ định mổ chưa?**","d":0},{"k":"p","x":"**Dữ kiện của ca và ý nghĩa**","d":0},{"k":"b","x":"**Lâm sàng:** nam 64 tuổi, đau thượng vị và hố chậu phải 2 ngày; bụng mềm, không phản ứng thành bụng; McBurney (+) (cần đối chiếu); đến 30/09 mới ghi khối hố chậu phải ấn đau vừa. Ảnh không có nhiệt độ, mạch, huyết áp nên chưa đánh giá được phản ứng viêm toàn thân.","d":0},{"k":"b","x":"**Viêm nhẹ đến vừa:** WBC 11.6 (chỉ cao nhẹ), NEUT 8.7 G/L (cao nhẹ; NEUT % vừa đúng 75), CRP 84.9 (cao khoảng 8 lần giới hạn trên là 10). CRP tăng rõ hơn bạch cầu nghĩa là quá trình viêm đã có vài ngày, đủ thời gian để CRP lên.","d":0},{"k":"b","x":"**Siêu âm 28/09:** thành hồi-manh tràng dày giảm âm; ruột thừa nghi sau manh tràng đường kính khoảng 6 mm có thâm nhiễm viêm; hạch phản ứng hố chậu phải khoảng 10 mm. Ruột thừa 6 mm chỉ ở ngưỡng, nên hình ảnh chưa đủ chẩn đoán xác định.","d":0},{"k":"b","x":"**CT có cản quang:** thành manh tràng phù nề, thâm nhiễm mỡ xung quanh, ruột thừa chưa thấy viêm, không hạch lớn, không khí dịch tự do. Thâm nhiễm mỡ quanh manh tràng thường thấy trong viêm (viêm ruột thừa, viêm hồi-manh tràng, viêm quanh u); CT chưa mô tả khối u rõ, nhưng báo cáo vẫn đề nghị nội soi để phân biệt u.","d":0},{"k":"b","x":"**Hb 139, MCV 93.2:** không thiếu máu, không gợi ý mất máu mạn; điều này hơi ngược với ung thư đại tràng phải tiến triển nhưng không loại trừ được u.","d":0},{"k":"b","x":"**CEA 4.51 ng/mL:** không dùng để chẩn đoán (tăng nhẹ ở viêm, hút thuốc); ngưỡng tham chiếu bị cắt khỏi ảnh nên chưa diễn giải chắc.","d":0},{"k":"p","x":"**Suy luận của AI (cần đối chiếu với phẫu thuật viên): 3 chẩn đoán còn mở**","d":0},{"k":"b","x":"**Viêm ruột thừa (nhất là thể sau manh tràng):** ủng hộ bởi đau hố chậu phải, McBurney (+), siêu âm ruột thừa 6 mm có thâm nhiễm, CRP cao; chống lại bởi CT chưa thấy viêm ruột thừa, không đau chuyển vị rõ (chưa ghi).","d":0},{"k":"b","x":"**Viêm hồi-manh tràng** (nhiễm khuẩn như Yersinia, Campylobacter; hoặc bệnh Crohn): ủng hộ bởi thành hồi-manh tràng dày, phù nề, hạch hố chậu phải; cần hỏi tiêu chảy, sốt.","d":0},{"k":"b","x":"**U manh tràng (ung thư, hoặc u ruột thừa):** ở người 64 tuổi, u làm tắc lỗ ruột thừa có thể gây viêm ruột thừa, và u có thể thể hiện bằng thành dày, thâm nhiễm mỡ, hạch. Phải loại trừ trước khi chốt kế hoạch mổ.","d":0},{"k":"p","x":"**Có chỉ định mổ chưa? (theo dữ kiện trong ảnh)**","d":0},{"k":"b","x":"**Chưa thấy chỉ định mổ cấp cứu:** không viêm phúc mạc (không phản ứng thành bụng), CT không thấy khí dịch tự do, áp xe hay tắc ruột, chưa thấy dấu huyết động bất thường. Xử trí hiện tại (kháng sinh, theo dõi sát, hoàn thiện chẩn đoán bằng nội soi) hợp lý.","d":0},{"k":"b","x":"**Chưa đủ cơ sở cho mổ theo kế hoạch ung thư:** chưa có mô bệnh học. Cắt đại tràng phải cần chẩn đoán ung thư bằng sinh thiết, phân giai đoạn (CT ngực-bụng-chậu), CEA nền và nội soi toàn bộ đại tràng (loại u đồng thời).","d":0},{"k":"b","x":"**Chưa đủ cơ sở để mổ cắt ruột thừa thường quy:** chẩn đoán viêm ruột thừa chưa được CT xác nhận; và ở người trên 40 tuổi nghi có khối, phẫu thuật viên cần tính đến khả năng phải cắt đại tràng phải khi vào bụng.","d":0},{"k":"b","x":"**Điều kiện đổi sang mổ:** dấu viêm phúc mạc mới; sốt cao, WBC hoặc CRP tăng dù kháng sinh 48 đến 72 giờ; khối hố chậu phải to lên hoặc thành áp xe; thủng hoặc tắc ruột; mô bệnh học ác tính (mổ theo kế hoạch ung thư).","d":0},{"k":"p","x":"**CLS nên có để trả lời câu 1 (chưa thấy trong ảnh)**","d":0},{"k":"b","x":"**Nội soi đại tràng toàn bộ kèm sinh thiết:** xét nghiệm quyết định. Đang chờ nội soi; thời điểm và cách chuẩn bị đại tràng cần bàn với bác sĩ nội soi và phẫu thuật viên vì nội soi hoặc uống thuốc chuẩn bị liều lớn có thể bất lợi khi còn nghi thủng, tắc hoặc viêm phúc mạc.","d":0},{"k":"b","x":"**WBC, NEUT, CRP lặp sau 24 đến 48 giờ kháng sinh:** xu hướng có giá trị hơn một con số đơn lẻ; đến nay chỉ có CBC ngày 28/09 và CRP ngày 29/09.","d":0},{"k":"b","x":"**Sinh hiệu, nhiệt độ và khám bụng lặp:** đã tăng theo dõi lên 6 giờ/lần; ghi cả kích thước khối hố chậu phải để so sánh.","d":0},{"k":"b","x":"**Điểm Alvarado hoặc AIR:** hiện chưa tính được vì thiếu chán ăn, nôn, sốt, đau chuyển vị; nên hỏi và ghi đủ.","d":0},{"k":"b","x":"**Siêu âm lặp hoặc CT lại:** khi khối hố chậu phải to lên, sốt, ăn kém, hoặc nghi áp xe.","d":0},{"k":"b","x":"**Tổng phân tích nước tiểu:** rẻ, giúp loại nguyên nhân tiết niệu (có sỏi thận phải 3 mm, không ứ nước).","d":0},{"k":"b","x":"**Cấy máu, cấy phân:** khi có sốt cao hoặc tiêu chảy (nghi viêm hồi-manh tràng nhiễm khuẩn).","d":0},{"k":"b","x":"**Giải phẫu bệnh:** mọi mẫu sinh thiết và mọi bệnh phẩm cắt (ruột thừa, đại tràng).","d":0},{"k":"b","x":"**CT ngực-bụng-chậu phân giai đoạn:** chỉ khi có mô bệnh học ác tính.","d":0},{"k":"p","x":"**CÂU 2. Nếu mổ, bệnh nhân có chịu đựng được không? (theo dữ kiện đã có)**","d":0},{"k":"b","x":"**Đông máu:** PT 12.0 giây, INR 1.06, PT 92%, APTT 27.0 giây (tỷ lệ 0.87), tiểu cầu 238 G/L đều bình thường; không cản trở mổ hay gây tê vùng. Fibrinogen 4.39 g/L (cao nhẹ) là protein pha cấp cùng chiều với CRP 84.9, không có nghĩa tình trạng tăng đông thật sự; dù vậy nguy cơ huyết khối sau mổ ở người 64 tuổi vẫn cần dự phòng theo thang điểm của bệnh viện.","d":0},{"k":"b","x":"**Đường huyết:** glucose 5.35 mmol/L bình thường; không cần HbA1c thường quy nếu không có tiền sử đái tháo đường.","d":0},{"k":"b","x":"**Thận và điện giải:** creatinin 79.3 µmol/L (eGFR CKD-EPI 2021 ước khoảng 95 mL/phút/1.73 m², AI tự tính), ure 4.66, Na 136.8, K 3.88, Cl 102. Đã dùng thuốc cản quang i-ốt để chụp CT; nếu eGFR trên 60 thì nguy cơ tổn thương thận do cản quang thấp, nhưng nên lặp creatinin và điện giải trước mổ nếu nhịn ăn lâu, mất dịch hoặc dùng thuốc kháng viêm không steroid.","d":0},{"k":"b","x":"**Gan:** AST 22.8, ALT 12.3, bilirubin toàn phần 7.3, trực tiếp 1.9 đều bình thường; chuyển hoá thuốc mê và giảm đau thuận lợi.","d":0},{"k":"b","x":"**Dinh dưỡng:** albumin 38.3 g/L bình thường (nguy cơ biến chứng thấp hơn so với dưới 30 g/L). Prealbumin 3.4 µmol/L thấp, nhưng prealbumin là protein âm tính pha cấp, giảm theo viêm (CRP 84.9) nên không dùng riêng để kết luận suy dinh dưỡng; cần cân nặng, BMI, mức sụt cân, thang sàng lọc dinh dưỡng (NRS-2002, MUST).","d":0},{"k":"b","x":"**Huyết học:** Hb 139 g/L, Hct 41.7%, không thiếu máu. Nhóm máu B, Rh(D) dương đã có; chưa thấy sàng lọc kháng thể bất thường hay thử phản ứng chéo (nên làm nếu chuẩn bị cắt đại tràng).","d":0},{"k":"b","x":"**Tim phổi:** chưa thấy điện tâm đồ hay X-quang ngực trong ảnh; khám tim phổi bình thường, không ho, không khó thở. Ở người 64 tuổi mổ trong ổ bụng (nguy cơ trung bình), điện tâm đồ là hợp lý; X-quang ngực hoặc siêu âm tim tuỳ tiền sử và triệu chứng (hướng dẫn ESC/ESAIC 2022 về phẫu thuật ngoài tim, cần đối chiếu). Chưa có phân loại ASA, tiền sử tăng huyết áp, tim mạch, hút thuốc, COPD, hay thuốc đang dùng (kháng đông, kháng kết tập).","d":0},{"k":"b","x":"**Xét nghiệm thường quy trước mổ ở nhiều cơ sở (HBsAg, HIV, anti-HCV):** chưa thấy trong ảnh.","d":0},{"k":"b","x":"**Kết luận của AI:** các chỉ số chịu đựng mổ trong ảnh nhìn chung tốt (đông máu, đường huyết, thận, gan, điện giải, Hb đều bình thường). Còn thiếu điện tâm đồ, X-quang ngực, phân loại ASA và bệnh sử nền; nguy cơ chính là tuổi 64 và tình trạng viêm đang hoạt động.","d":0},{"k":"p","x":"**CÂU 3. Sau mổ: CLS có phù hợp thực tế không?**","d":0},{"k":"p","x":"**Bệnh nhân chưa mổ đến 30/09, nên phần này gồm nhận xét CLS đã làm và kế hoạch theo từng tình huống.**","d":0},{"k":"b","x":"**Bộ 17 xét nghiệm đã làm so với diễn tiến thực tế:**","d":0},{"k":"b","x":"Công thức máu, CRP, sinh hoá, đông máu, nhóm máu: phù hợp cả để đánh giá viêm lẫn chuẩn bị mổ. Đông máu và nhóm máu được chỉ định lúc 29/09 08:05 gợi ý mổ đã được cân nhắc (suy luận của AI).","d":1},{"k":"b","x":"CEA: hợp lý làm giá trị nền khi nghi u, nhưng không phải xét nghiệm chẩn đoán; quyết định vẫn dựa vào nội soi và giải phẫu bệnh.","d":1},{"k":"b","x":"Prealbumin: ít giá trị khi CRP đang cao; có thể thay bằng cân nặng, BMI, sàng lọc dinh dưỡng.","d":1},{"k":"b","x":"Thiếu: xu hướng WBC và CRP sau 29/09, sinh hiệu, điện tâm đồ, nội soi.","d":1},{"k":"b","x":"**Nếu cắt ruột thừa nội soi, không biến chứng:** không cần xét nghiệm thường quy hằng ngày nếu lâm sàng ổn; giải phẫu bệnh ruột thừa là bắt buộc ở tuổi này (loại u ruột thừa, u thần kinh nội tiết); nếu kết quả nghi u manh tràng thì nội soi đại tràng sau mổ.","d":0},{"k":"b","x":"**Nếu cắt đại tràng phải:**","d":0},{"k":"b","x":"Ngày 1 đến 3: công thức máu (Hb, WBC), CRP, điện giải, creatinin, albumin.","d":1},{"k":"b","x":"CRP thường đỉnh ngày 2 đến 3 rồi giảm; CRP ngày 3 cao trên khoảng 170 mg/L hoặc tăng lại là dấu cảnh báo rò miệng nối (phân tích gộp Singh 2014, cần đối chiếu con số).","d":1},{"k":"b","x":"CT bụng có cản quang khi nghi rò hoặc áp xe (sốt, đau tăng, mạch nhanh, liệt ruột kéo dài).","d":1},{"k":"b","x":"Giải phẫu bệnh: giai đoạn TNM, số hạch (từ 12 hạch trở lên), tình trạng MMR hoặc MSI; CEA nền và theo dõi sau mổ theo giai đoạn.","d":1},{"k":"b","x":"**Bất kỳ tình huống nào:** chỉ định lại CLS khi có thay đổi lâm sàng (sốt, nôn, chướng bụng, đau tăng, vàng da) thay vì xét nghiệm thường quy hằng ngày.","d":0}],"Phân tích điều trị (AI)":[{"k":"p","x":"**Phân tích theo mốc thời gian**","d":0},{"k":"p","x":"**Mốc 28/09 16:00 (vào khoa)**","d":0},{"k":"b","x":"**Clindamycin 600 mg truyền tĩnh mạch:** phủ cầu khuẩn Gram dương và vi khuẩn kỵ khí (Bacteroides) nhưng không phủ trực khuẩn Gram âm đường ruột (E. coli, Klebsiella). Nhiễm khuẩn ổ bụng nguồn ruột (viêm ruột thừa, viêm hồi-manh tràng) cần phổ phủ Gram âm và kỵ khí, nên clindamycin dùng đơn độc là chưa đủ phổ. Phác đồ chuẩn thường là cephalosporin thế hệ 3 (hoặc thế hệ 2) cộng metronidazole, amoxicillin-clavulanate, hoặc piperacillin-tazobactam nếu nặng (WSES Jerusalem 2020, IDSA/SIS; cần đối chiếu).","d":0},{"k":"b","x":"**Chưa thấy thuốc giảm đau:** giảm đau không che lấp dấu hiệu bụng ngoại khoa và không làm chậm chẩn đoán (bằng chứng từ các thử nghiệm, cần đối chiếu), nên có thể dùng paracetamol.","d":0},{"k":"b","x":"**Ăn cơm, theo dõi 12 giờ/lần, chăm sóc cấp ba:** phù hợp khi chưa nghi bụng ngoại khoa cấp; nếu nghi viêm ruột thừa có thể phải mổ thì phẫu thuật viên thường muốn nhịn hoặc ăn nhẹ.","d":0},{"k":"p","x":"**Mốc 29/09 08:00**","d":0},{"k":"b","x":"**Clindamycin ngày 2, 2 ống (08:00 và 16:00), tương đương 1200 mg/ngày:** thấp hơn liều thường dùng trong nhiễm khuẩn ổ bụng (600 đến 900 mg mỗi 8 giờ); cần đối chiếu với phiếu đầy đủ và với bác sĩ điều trị.","d":0},{"k":"b","x":"**Xét nghiệm lúc 08:05 (đông máu, nhóm máu, CRP, CEA...):** phù hợp với việc vừa đánh giá viêm vừa chuẩn bị nội soi hoặc mổ.","d":0},{"k":"p","x":"**Mốc 30/09 07:42**","d":0},{"k":"b","x":"**Thêm cephalothin 2 g (ghi ngày thứ 2):**","d":0},{"k":"b","x":"Cephalosporin thế hệ 1 phủ Gram dương và một số Gram âm còn nhạy (E. coli, Klebsiella, Proteus nhạy cảm), không phủ kỵ khí (đã có clindamycin bù).","d":1},{"k":"b","x":"Tại Việt Nam tỷ lệ E. coli và Klebsiella tiết ESBL hoặc kháng cephalosporin cao, nên cần đối chiếu kháng sinh đồ của bệnh viện.","d":1},{"k":"b","x":"Phối hợp clindamycin và cephalothin phủ được Gram dương, Gram âm nhạy và kỵ khí, nhưng không tối ưu bằng phác đồ chuẩn (cephalosporin thế hệ 3 hoặc ceftriaxone cộng metronidazole; amoxicillin-clavulanate).","d":1},{"k":"b","x":"**Đánh giá đáp ứng sau 48 đến 72 giờ kháng sinh:** bệnh nhân vẫn đau, khối hố chậu phải mới được ghi nhận, nên chưa thấy đáp ứng rõ. Cần xu hướng WBC, CRP, sinh hiệu để quyết định tiếp tục kháng sinh, đổi phổ hay đổi hướng. Nếu khối là phlegmon hoặc áp xe nhỏ thì kháng sinh có thể đủ, có thể cần dẫn lưu; nếu là u thì kháng sinh không giải quyết được nguyên nhân.","d":0},{"k":"b","x":"**Naprozole-R 20 mg tiêm tĩnh mạch, 2 lần/ngày:** tên thương mại cần đối chiếu nhãn (theo hiểu biết của AI có thể là thuốc ức chế bơm proton). Chỉ định cho đau thượng vị nóng rát trong lúc đợi nội soi dạ dày; chưa có bằng chứng xuất huyết tiêu hoá. Nếu ăn uống được thì có thể chuyển đường uống. Lưu ý: thuốc ức chế bơm proton làm giảm độ nhạy của test tìm H. pylori (hơi thở, kháng nguyên phân, một phần sinh thiết); thường ngưng khoảng 2 tuần trước khi test nếu lâm sàng cho phép (cần đối chiếu).","d":0},{"k":"b","x":"**Men vi sinh (Biosubtyl-II) 3 viên/ngày:** hỗ trợ dự phòng tiêu chảy do kháng sinh (hiệu quả khiêm tốn); thành phần cần đối chiếu nhãn; uống cách xa thời điểm dùng kháng sinh đường uống nếu có.","d":0},{"k":"b","x":"**Theo dõi 6 giờ/lần, chăm sóc cấp hai, ăn cơm:** tăng mức theo dõi phản ánh mối lo ngại tăng sau khi thấy khối; hợp lý.","d":0},{"k":"p","x":"**Thời gian dùng kháng sinh (theo hướng xử trí, cần đối chiếu WSES 2020)**","d":0},{"k":"b","x":"**Điều trị bảo tồn viêm ruột thừa không biến chứng:** khoảng 7 đến 10 ngày (thử nghiệm CODA dùng 10 ngày, gồm truyền tĩnh mạch rồi uống).","d":0},{"k":"b","x":"**Cắt ruột thừa không biến chứng:** không cần kháng sinh sau mổ.","d":0},{"k":"b","x":"**Có biến chứng (thủng, hoại tử, áp xe) đã kiểm soát nguồn:** khoảng 3 đến 5 ngày, ngừng sớm nếu lâm sàng ổn (thử nghiệm STOP-IT: khoảng 4 ngày sau kiểm soát nguồn).","d":0},{"k":"p","x":"**Nội soi và chuẩn bị (thảo luận với phẫu thuật viên và bác sĩ nội soi)**","d":0},{"k":"b","x":"Nội soi đại tràng khi còn nghi thủng hoặc viêm phúc mạc là chống chỉ định tương đối; chuẩn bị đại tràng bằng dung dịch liều lớn có thể bất lợi khi nghi tắc hoặc viêm ruột thừa nặng.","d":0},{"k":"b","x":"Lựa chọn thường gặp ở người trên 40 tuổi viêm ruột thừa: nội soi đại tràng hoặc chụp đại tràng sau đợt viêm để loại u đại tràng phải; tỷ lệ u ở nhóm này khoảng vài phần trăm và khác nhau giữa các phân tích gộp (cần đối chiếu).","d":0},{"k":"p","x":"**Nếu tiến tới phẫu thuật**","d":0},{"k":"b","x":"**Nếu chẩn đoán viêm ruột thừa:** cắt ruột thừa nội soi; gửi giải phẫu bệnh.","d":0},{"k":"b","x":"**Nếu ung thư biểu mô manh tràng:** cắt đại tràng phải kèm cắt toàn bộ mạc treo (CME) và nạo hạch theo nguyên tắc ung thư; kháng sinh dự phòng trước rạch da; dự phòng huyết khối; phục hồi sau mổ tăng cường (ERAS) (cần đối chiếu hướng dẫn hiện hành của NCCN và ASCRS).","d":0},{"k":"p","x":"**Lưu ý dược lý cần nhớ**","d":0},{"k":"b","x":"Clindamycin làm tăng nguy cơ tiêu chảy do Clostridioides difficile và có thể tăng tác dụng của thuốc giãn cơ không khử cực dùng khi gây mê (cần đối chiếu).","d":0},{"k":"b","x":"Cephalothin ít dùng ở nhiều nơi; cần đối chiếu tên thuốc thương mại trên nhãn thực tế.","d":0},{"k":"p","x":"**Nguồn tham khảo (tôi chỉ đọc được tiêu đề khi tra cứu; số liệu ghi theo hiểu biết của AI, cần đối chiếu bản gốc):**","d":0},{"k":"b","x":"WSES Jerusalem guidelines 2020: chẩn đoán và điều trị viêm ruột thừa cấp","d":0},{"k":"b","x":"CODA: kháng sinh so với cắt ruột thừa (NEJM 2020)","d":0},{"k":"b","x":"Ung thư đại tràng phải ở bệnh nhân trên 40 tuổi viêm ruột thừa: tổng quan hệ thống và phân tích gộp","d":0},{"k":"b","x":"Nguy cơ ung thư đại tràng tăng sau viêm ruột thừa cấp (eClinicalMedicine 2023)","d":0}],"Thắc mắc lâm sàng":[{"k":"b","x":"**Chẩn đoán nào đúng nhất: viêm ruột thừa sau manh tràng, viêm hồi-manh tràng hay u manh tràng?** Điểm nào trên lâm sàng và CT giúp phân biệt (hình thái dày thành, thâm nhiễm mỡ, hạch, ruột thừa có viêm không)?","d":0},{"k":"b","x":"**Đã có chỉ định mổ chưa, và ngưỡng để chuyển từ theo dõi sang mổ là gì?** Sốt, CRP tăng, khối to lên, phản ứng thành bụng, hay mô bệnh học ác tính?","d":0},{"k":"b","x":"**Khối hố chậu phải ghi ngày 30/09 là mới xuất hiện hay 28/09 chưa ghi?** Đó là phlegmon hoặc áp xe, u, hay manh tràng viêm sờ thấy; có cần lặp hình ảnh không?","d":0},{"k":"b","x":"**Vì sao bắt đầu bằng clindamycin đơn độc rồi thêm cephalothin?** Phổ Gram âm và kỵ khí đã đủ chưa, có nên chuyển sang phác đồ chuẩn theo kháng sinh đồ?","d":0},{"k":"b","x":"**Nội soi đại tràng nên làm lúc nào** (khi còn viêm hay sau vài tuần) và chuẩn bị đại tràng thế nào cho an toàn?","d":0},{"k":"b","x":"**Nếu sinh thiết là ung thư:** cần thêm gì trước mổ (CT ngực-bụng-chậu, CEA nền, MMR hoặc MSI), và phẫu thuật gồm những bước nào?","d":0},{"k":"b","x":"**CEA 4.51 ng/mL diễn giải ra sao khi ngưỡng bị cắt khỏi ảnh và bệnh nhân đang có viêm?**","d":0}],"Kiến thức cần nắm":[{"k":"b","x":"**Điểm Alvarado (tối đa 10):** đau chuyển vị 1, chán ăn 1, buồn nôn hoặc nôn 1, đau hố chậu phải 2, phản ứng dội 1, sốt 1, bạch cầu tăng 2, chuyển trái 1. Điểm cao gợi ý nhiều khả năng viêm ruột thừa; thang điểm không thay CT ở ca nghi ngờ.","d":0},{"k":"b","x":"**Hình ảnh ruột thừa viêm:** đường kính trên khoảng 6 mm, không xẹp khi ép, thành dày, thâm nhiễm mỡ xung quanh; siêu âm âm tính không loại trừ viêm ruột thừa, CT nhạy hơn.","d":0},{"k":"b","x":"**Kháng sinh đơn thuần (CODA 2020):** không kém về kết cục sức khoẻ tại 30 ngày; khoảng 29% bệnh nhân cần cắt ruột thừa trong 90 ngày, cao hơn ở người có sỏi phân (cần đối chiếu con số). Ở người lớn tuổi hoặc nghi có khối, cần loại u trước khi chọn kháng sinh đơn thuần.","d":0},{"k":"b","x":"**Người từ 40 tuổi trở lên viêm ruột thừa:** nguy cơ u đại tràng phải và u ruột thừa cao hơn dân số chung; nhiều khuyến cáo nêu nên nội soi hoặc chụp đại tràng sau đợt viêm (cần đối chiếu).","d":0},{"k":"b","x":"**Ung thư đại tràng phải:** thường thiếu máu thiếu sắt, khối hố chậu phải, ít tắc ruột vì lòng đại tràng phải rộng và phân lỏng; phẫu thuật chuẩn là cắt đại tràng phải kèm CME, lấy từ 12 hạch trở lên.","d":0},{"k":"b","x":"**CEA:** không dùng để chẩn đoán hay tầm soát; dùng làm giá trị nền trước mổ và theo dõi sau mổ; tăng nhẹ ở người hút thuốc, viêm, bệnh gan.","d":0},{"k":"b","x":"**Bẫy MCQ:** “PCT” trong công thức máu là plateletcrit, không phải procalcitonin. Prealbumin và fibrinogen là protein pha cấp: prealbumin giảm khi viêm nên không kết luận suy dinh dưỡng riêng theo prealbumin; fibrinogen tăng khi viêm không có nghĩa tăng đông thực sự.","d":0},{"k":"b","x":"**Clindamycin:** không phủ Gram âm đường ruột; tăng nguy cơ viêm đại tràng do C. difficile; tăng tác dụng của thuốc giãn cơ không khử cực.","d":0},{"k":"b","x":"**Sau cắt đại tràng:** CRP ngày 3 cao là dấu cảnh báo rò miệng nối (cần đối chiếu ngưỡng).","d":0},{"k":"b","x":"**Chuẩn bị mổ:** nhóm máu và sàng lọc kháng thể trước cắt đại tràng; điện tâm đồ ở người từ 50 đến 65 tuổi mổ trong ổ bụng (cần đối chiếu).","d":0}],"Kiến thức cần đào sâu":[{"k":"b","x":"**Viêm ruột thừa ở người lớn tuổi và nguy cơ u đại tràng phải:** tỷ lệ u theo tuổi, đặc điểm CT phân biệt viêm ruột thừa với u manh tràng, chiến lược nội soi sau đợt viêm. Gợi ý nguồn: các phân tích gộp về ung thư đại tràng phải ở người trên 40 tuổi viêm ruột thừa, phân tích dân số eClinicalMedicine 2023, WSES Jerusalem 2020.","d":0},{"k":"b","x":"**Kháng sinh đơn thuần và phẫu thuật (CODA, APPAC) và ngoại lệ ở người trên 60 tuổi hoặc có khối:** khi nào không nên chọn kháng sinh đơn thuần; cập nhật WSES 2020.","d":0},{"k":"b","x":"**Kháng sinh trong nhiễm khuẩn ổ bụng theo kháng sinh đồ Việt Nam:** vấn đề ESBL, lựa chọn phác đồ, thời gian điều trị. Gợi ý nguồn: hướng dẫn IDSA và SIS, WHO AWaRe, kháng sinh đồ của bệnh viện.","d":0},{"k":"b","x":"**Phẫu thuật ung thư đại tràng phải:** cắt toàn bộ mạc treo (CME), nạo hạch, đánh giá MMR hoặc MSI, ERAS. Gợi ý nguồn: hướng dẫn NCCN colon cancer, ESMO 2020, ASCRS 2022.","d":0}]}}],
    ["TH-001","Tiêu hoá (đi thêm)","2026-09-28",1,"3ebcb1425c81811b82cac88f1fb14ffe","Đang nằm viện","111110",{"d":"U gan đa ổ, ung thư biểu mô tế bào gan (C22.0), CT gợi ý tái phát, AFP 705 IU/mL; dự kiến TACE trước ghép gan","c":[["Bắc cầu và hạ giai đoạn bằng TACE trước ghép gan trong HCC: Milan, UCSF và ngưỡng AFP 400/1000","3ebcb1425c81811ca784d11248e7654e"]],"s":{"CLS":[{"k":"t","h":true,"r":[["Chỉ số","Tham chiếu","29/09"],["Ure máu (mmol/L)","1.7–8.3","4.4"],["Creatinin (µmol/L)","Nam: từ 62 (giới hạn trên bị cắt khỏi ảnh)","63.1"],["Glucose (mmol/L)","3.9–6.4","3.65"],["Natri (mmol/L)","135–145","140.9"],["Kali (mmol/L)","3.5–5.0","3.30"],["Chloride (mmol/L)","96–110","104.9"],["ALT / SGPT (U/L)","Nam: <41","18.0"],["AST / SGOT (U/L)","Nam: <37","16.6"],["Protein toàn phần (g/L)","66–87","68.4"],["Albumin (g/L)","35–52","42.1"],["AFP (IU/mL)","<5.8","705.0"],["PIVKA-II (ng/mL)","<28.4","13.45"],["PT (giây)","10–13","–"],["INR","1–1.2","–"],["PT (%)",">70","–"],["APTT (giây)","25.6–38.4","–"],["APTT ratio","0.8–1.2","–"],["Fibrinogen (g/L)","2.0–4.0","–"],["Bạch cầu WBC (G/L)","từ 4 (giới hạn trên bị cắt)","10.09"],["NEUT (% / G/L)","từ 45 / từ 1.8 (giới hạn trên bị cắt)","55.2 / 5.57"],["LYM (% / G/L)","từ 20 / từ 0.8 (giới hạn trên bị cắt)","34.7 / 3.50"],["MONO (% / G/L)","từ 4 / từ 0.16 (giới hạn trên bị cắt)","7.6 / 0.77"],["EOS (% / G/L)","từ 2 / từ 0.08 (giới hạn trên bị cắt)","2.1 / 0.21"],["BASO (% / G/L)","từ 0.0 (giới hạn trên bị cắt)","0.4 / 0.04"],["Hồng cầu RBC (T/L)","từ 3.8 (giới hạn trên bị cắt)","5.31"],["Hemoglobin (g/L)","từ 120 (giới hạn trên bị cắt)","146"],["Hematocrit (%)","từ 34 (giới hạn trên bị cắt)","44.4"],["MCV (fL)","từ 78 (giới hạn trên bị cắt)","83.6"],["MCH (pg)","từ 24 (giới hạn trên bị cắt)","27.5"],["MCHC (g/L)","từ 315 (giới hạn trên bị cắt)","329"],["RDW-CV (%)","từ 11 (giới hạn trên bị cắt)","12.4"],["RDW-SD (fL)","từ 37 (giới hạn trên bị cắt)","37.5"],["Tiểu cầu PLT (G/L)","từ 150 (giới hạn trên bị cắt)","222"],["MPV (fL)","từ 7.0 (giới hạn trên bị cắt)","9.5"]]},{"k":"p","x":"Màu: xanh = thấp hơn tham chiếu, đỏ = cao hơn, đen = bình thường.","d":0},{"k":"p","x":"**Ghi chú về bảng:**","d":0},{"k":"b","x":"Tham chiếu lấy từ ảnh phiếu Minh gửi. Chỗ ghi “giới hạn trên bị cắt” là khung ảnh chụp mất phần cuối của khoảng tham chiếu, nên chưa tô màu; cần bảng tham chiếu đầy đủ của phòng xét nghiệm để hoàn thiện. Đơn vị các chỉ số công thức máu không nhìn thấy trong ảnh, ghi theo đơn vị thường dùng.","d":0},{"k":"b","x":"Danh sách kết quả của hệ thống chỉ đánh dấu bất thường ở AFP, điện giải đồ và glucose; các mục còn lại (công thức máu, PIVKA-II, đông máu, sinh hoá khác) không bị đánh dấu.","d":0},{"k":"b","x":"PT, INR, APTT, fibrinogen đã có kết quả nhưng cột giá trị không hiện trong ảnh: cần bổ sung số cụ thể.","d":0},{"k":"p","x":"**Chẩn đoán hình ảnh:**","d":0},{"k":"b","x":"**Siêu âm ổ bụng 29/09/2026 (thực hiện 14:59, trả kết quả 15:01):**","d":0},{"k":"b","x":"Gan: không lớn, bờ đều, đồng nhất. HPT VIII có cấu trúc giảm âm không đồng nhất, bờ đều, giới hạn rõ, khoảng 16×11 mm. HPT VII cấu trúc tương tự, khoảng 9 mm.","d":1},{"k":"b","x":"Mật: túi mật không sỏi, không dãn; đường mật không sỏi, không dãn.","d":1},{"k":"b","x":"Lách không lớn, đồng dạng. Tụy bình thường.","d":1},{"k":"b","x":"Thận phải và thận trái: không sỏi, không ứ nước, chủ mô bình thường.","d":1},{"k":"b","x":"Bàng quang: thành không dày, không cặn lắng, không sỏi. Màng phổi: không dịch.","d":1},{"k":"b","x":"Kết luận: theo dõi u gan phải.","d":1},{"k":"b","x":"**CT (theo ghi chép y lệnh 29/09):** hình ảnh ung thư gan tái phát. Phim và báo cáo CT chưa có trong ảnh gửi.","d":0},{"k":"p","x":"**CLS đã chỉ định nhưng chưa thấy kết quả trong ảnh:**","d":0},{"k":"b","x":"Định nhóm máu hệ ABO, Rh(D) (kỹ thuật Scangel/Gelcard trên máy tự động).","d":0},{"k":"b","x":"Hai mục chẩn đoán hình ảnh hoặc thăm dò chức năng còn lại (tổng 3 mục, đã thấy siêu âm ổ bụng); chưa rõ tên.","d":0}],"Điều trị":[{"k":"p","x":"**28/09 (14:05):**","d":0},{"k":"b","x":"Boganic Forte (đã cấp phát; liều và số lần/ngày không thấy trong ảnh)","d":0},{"k":"p","x":"**29/09 (07:18):**","d":0},{"k":"b","x":"Boganic Forte (đã cấp phát)","d":0},{"k":"p","x":"**30/09 (07:17):**","d":0},{"k":"b","x":"Boganic Forte (đã cấp phát)","d":0},{"k":"p","x":"**01/10 (07:17), y lệnh lập sẵn:**","d":0},{"k":"b","x":"Boganic Forte (chưa ở tình trạng “đã cấp phát”)","d":0},{"k":"p","x":"**Y lệnh chăm sóc và theo dõi:**","d":0},{"k":"b","x":"Theo dõi mạch, nhiệt, huyết áp: 12 giờ/lần (28/09), đổi thành 8 giờ/lần từ 29/09","d":0},{"k":"b","x":"Chăm sóc cấp ba","d":0},{"k":"b","x":"Dinh dưỡng: BT02-CƠM (28/09), đổi thành BT02-CHÁO từ 29/09","d":0},{"k":"p","x":"**Kế hoạch ghi trong y lệnh:**","d":0},{"k":"b","x":"Can thiệp TACE trước ghép gan (chưa thấy ngày thực hiện hay y lệnh cụ thể)","d":0}],"Phân tích đề nghị CLS (AI)":[{"k":"p","x":"**Dữ kiện của ca (đã có) và ý nghĩa**","d":0},{"k":"b","x":"**AFP 705 IU/mL (gấp khoảng 120 lần giới hạn trên):** AFP do tế bào gan biến đổi ác tính tiết ra, nhưng không phải HCC nào cũng tăng và AFP không đặc hiệu tuyệt đối. Với ghép gan, mốc quan trọng là 400 và 1000 ng/mL (xem mục Phân tích điều trị). AFP 705 nằm giữa hai mốc.","d":0},{"k":"b","x":"**PIVKA-II 13.45 ng/mL (bình thường):** PIVKA-II là prothrombin thiếu carboxyl hoá do tế bào ung thư gan thiếu enzym carboxyl hoá phụ thuộc vitamin K. AFP rất cao nhưng PIVKA-II bình thường là hai chỉ điểm không đồng thuận. Suy luận của AI: có thể u nhỏ (PIVKA-II thường thấp ở ổ nhỏ), kiểu tiết AFP là chính, hoặc AFP tăng do nguồn khác; cần đối chiếu.","d":0},{"k":"b","x":"**Chức năng gan trên số hiện có:** ALT 18, AST 16.6, albumin 42.1, protein toàn phần 68.4, tiểu cầu 222, lách không lớn trên siêu âm. Chưa có dấu hiệu suy chức năng gan hay tăng áp cửa. FIB-4 tính được khoảng 0.62 (tuổi 35, AST 16.6, tiểu cầu 222, ALT 18), dưới 1.3 nên nguy cơ xơ hoá tiến triển thấp; FIB-4 chỉ là công cụ sàng lọc, không thay đàn hồi gan.","d":0},{"k":"b","x":"**Kali 3.30 và glucose 3.65 mmol/L:** đều thấp nhẹ, đã được hệ thống đánh dấu. Xem mục Phân tích điều trị.","d":0},{"k":"b","x":"**Siêu âm:** 2 ổ giảm âm nhỏ (16×11 mm và 9 mm) ở HPT VIII và VII. Siêu âm kém nhạy hơn CT/MRI với ổ nhỏ nên không đủ để đếm số ổ hay phân giai đoạn; cần đối chiếu với CT.","d":0},{"k":"b","x":"**Đông máu và nhóm máu:** cần cho chuẩn bị TACE (chọc động mạch, nguy cơ chảy máu), chấm Child-Pugh, và chuẩn bị ghép gan (tương hợp ABO).","d":0},{"k":"p","x":"**CLS còn thiếu, nên cân nhắc (kèm điều kiện)**","d":0},{"k":"b","x":"**Bilirubin toàn phần, trực tiếp; GGT, ALP:** cần để chấm Child-Pugh và ALBI, và bilirubin cao là yếu tố làm cân nhắc lại TACE. Chỉ định: trước TACE.","d":0},{"k":"b","x":"**INR và số cụ thể PT, APTT, fibrinogen:** bổ sung số vào bảng CLS.","d":0},{"k":"b","x":"**HBsAg, anti-HCV (kèm HBV DNA nếu HBsAg dương), anti-HIV:** xác định nguyên nhân gan mạn; virus viêm gan B có thể tái hoạt khi TACE hoặc hoá trị; cần trong hồ sơ ghép gan. Chỉ định: nên làm ngay.","d":0},{"k":"b","x":"**CT hoặc MRI gan nhiều pha (nếu chưa có bản đầy đủ):** đếm số ổ và kích thước, huyết khối tĩnh mạch cửa, giải phẫu động mạch gan cho TACE, hạch. Lấy phim và báo cáo CT ngoại viện để đối chiếu.","d":0},{"k":"b","x":"**CT ngực (± xạ hình xương nếu có triệu chứng):** loại trừ di căn ngoài gan trước khi bàn ghép gan.","d":0},{"k":"b","x":"**Đàn hồi gan (FibroScan hoặc tương đương):** bệnh nhân trẻ, men gan bình thường, tiểu cầu bình thường, gan đồng nhất trên siêu âm: cần biết có xơ gan hay không vì đổi cách chẩn đoán và cách chọn điều trị.","d":0},{"k":"b","x":"**Sinh thiết u (cân nhắc):** tiêu chuẩn chẩn đoán HCC bằng hình ảnh không sinh thiết theo AASLD/EASL và LI-RADS áp dụng cho nhóm nguy cơ (xơ gan, viêm gan B mạn, tiền sử HCC); nếu bệnh nhân không thuộc nhóm này thì hình ảnh không đủ, cần sinh thiết, nhất là khi kết quả quyết định ghép gan. Cần đối chiếu với hội chẩn.","d":0},{"k":"b","x":"**Nếu hình ảnh không điển hình hoặc bệnh nhân không có yếu tố nguy cơ gan (nam trẻ, AFP cao, PIVKA-II thấp):** β-hCG, LDH và siêu âm tinh hoàn để loại trừ u tế bào mầm ác tính di căn gan. Đây là chẩn đoán phân biệt hiếm nhưng điều trị hoàn toàn khác; mức chỉ định phụ thuộc hình ảnh CT.","d":0},{"k":"p","x":"**CLS chưa cần, hoặc nên tránh làm thừa**","d":0},{"k":"b","x":"Không cần lặp AFP hằng ngày; đánh giá đáp ứng nên làm sau TACE (khoảng 4 đến 6 tuần) cùng CT/MRI theo mRECIST.","d":0},{"k":"b","x":"Không cần lặp siêu âm ổ bụng khi đã có CT/MRI đầy đủ.","d":0}],"Phân tích điều trị (AI)":[{"k":"p","x":"**1. TACE trước ghép gan (kế hoạch trong y lệnh)**","d":0},{"k":"b","x":"**Cơ chế:** tắc mạch cấp máu cho u (u gan lấy máu chủ yếu từ động mạch gan, mô gan lành chủ yếu từ tĩnh mạch cửa) kèm hoá chất tại chỗ, gây thiếu máu và hoại tử u trong khi tương đối bảo tồn nhu mô gan.","d":0},{"k":"b","x":"**Vai trò “bắc cầu” (bridging) và “hạ giai đoạn” (downstaging):** BCLC 2022 đưa hạ giai đoạn bằng TACE hoặc TARE vào thuật toán như một đường dẫn tới ghép gan; khi chờ ghép quá 6 tháng thì có thể dùng đốt u, TACE hoặc TARE để bắc cầu.","d":0},{"k":"b","x":"**AFP và chỉ định ghép:** chính sách UNOS: AFP trên 1000 ng/mL phải hạ xuống dưới 500 ng/mL (và duy trì khoảng 3 tháng) mới được điểm ngoại lệ HCC. Một số hướng dẫn được tổng quan năm 2026 coi AFP trên 400 là chống chỉ định tương đối và trên 1000 là tuyệt đối. AFP 705 của bệnh nhân này chưa vượt 1000 nhưng đã trên 400, nên đáp ứng AFP sau TACE có giá trị tiên lượng.","d":0},{"k":"b","x":"**Điều kiện trước TACE (theo thực hành chung, cần đối chiếu quy trình của trung tâm):** chức năng gan còn bù (Child-Pugh A đến B7), tĩnh mạch cửa thông, bilirubin không tăng cao, creatinin cho phép dùng cản quang (creatinin hiện 63.1 µmol/L), thể trạng tốt. Hiện còn thiếu bilirubin, INR số, CT đầy đủ để khẳng định.","d":0},{"k":"b","x":"**Sau thủ thuật:** hội chứng sau tắc mạch (sốt, đau hạ sườn phải, buồn nôn) thường gặp; theo dõi men gan, bilirubin, creatinin; dự phòng nôn và giảm đau theo y lệnh.","d":0},{"k":"b","x":"**Khuyến nghị thực hành (để Minh cân nhắc):** hội chẩn đa chuyên khoa (ngoại gan mật/ghép, can thiệp mạch, tiêu hoá, ung bướu) để xác định mục tiêu là bắc cầu hay hạ giai đoạn, và thời gian chờ ghép tại nơi bệnh nhân dự định ghép.","d":0},{"k":"p","x":"**2. Boganic Forte (thuốc duy nhất trong y lệnh)**","d":0},{"k":"b","x":"**Thành phần theo nhãn Traphaco:** cao actiso, cao rau đắng đất, cao bìm bìm (khoảng 200 mg, 150 mg, 16 mg mỗi viên nang mềm theo nhiều nguồn; hàm lượng khác giữa các phiên bản nhãn, cần đối chiếu nhãn thuốc thực tế).","d":0},{"k":"b","x":"**Chỉ định ghi trên nhãn:** hỗ trợ suy giảm chức năng gan, đặc biệt do rượu bia. Chống chỉ định: mẫn cảm, viêm tắc ruột, tỳ vị hư hàn (phân lỏng, tiêu chảy). Tá dược có dầu đậu nành.","d":0},{"k":"b","x":"**Nhận xét:** đây là thuốc thảo dược hỗ trợ; theo hiểu biết của AI, không thấy trong các khuyến cáo điều trị HCC chính (BCLC, EASL, AASLD) và không thay được điều trị đặc hiệu u. Chức năng gan hiện bình thường (ALT, AST, albumin) nên cần hỏi lại mục đích chỉ định. Bìm bìm có tác dụng nhuận tràng, lợi tiểu theo nhãn: cần cân nhắc khi kali thấp.","d":0},{"k":"p","x":"**3. Kali 3.30 và glucose 3.65 mmol/L**","d":0},{"k":"b","x":"**Kali thấp nhẹ:** cần tìm nguyên nhân (ăn cháo nên nhập kali thấp; thuốc nhuận tràng hoặc lợi tiểu; mất qua tiêu hoá), kiểm tra magie. Nên đưa kali về mức bình thường trước thủ thuật vì hạ kali gây loạn nhịp và liệt ruột; bù đường uống hoặc thực phẩm giàu kali, lặp lại xét nghiệm. Liều bù cần theo y lệnh của bác sĩ điều trị.","d":0},{"k":"b","x":"**Glucose 3.65 lúc 07:18:** mẫu máu thời điểm đói, thấp nhẹ. Đối chiếu lại bữa ăn và lặp lại; nếu tái diễn thì tìm nguyên nhân (nhịn ăn kéo dài, rối loạn nội tiết, hiếm gặp hạ đường huyết do u tiết IGF-II).","d":0},{"k":"p","x":"**4. Đau hạ sườn phải**","d":0},{"k":"b","x":"Y lệnh ghi bệnh nhân đau hạ sườn phải nhưng thuốc chỉ có Boganic Forte. Nên đánh giá mức đau (thang VAS), nguyên nhân (u, căng bao gan, nguyên nhân khác), và cân nhắc giảm đau bậc 1 với liều paracetamol thận trọng theo chức năng gan; tránh NSAID nếu chưa cân nhắc nguy cơ chảy máu và thận trước thủ thuật. Cần đối chiếu với bác sĩ điều trị.","d":0},{"k":"p","x":"**Nguồn tham khảo:**","d":0},{"k":"b","x":"BCLC strategy for prognosis prediction and treatment recommendation: the 2022 update, J Hepatol","d":0},{"k":"b","x":"2022 update of BCLC treatment algorithm: what is new for interventional radiologists, CVIR","d":0},{"k":"b","x":"Liver transplantation for HCC: patient selection and downstaging, Gastroenterol Rep 2026","d":0},{"k":"b","x":"Hepatocellular carcinoma, alpha fetoprotein and liver allocation, Curr Oncol 2022","d":0},{"k":"b","x":"Boganic Forte, nhà sản xuất Traphaco","d":0}],"Thắc mắc lâm sàng":[{"k":"b","x":"**“Tái phát” hay phát hiện lần đầu?** Y lệnh ghi CT ung thư gan tái phát nhưng tiền sử sống khỏe. Bệnh nhân đã từng điều trị ung thư gan chưa? Câu trả lời đổi cách phân giai đoạn BCLC và chiến lược điều trị.","d":0},{"k":"b","x":"**Nền gan của bệnh nhân là gì?** ALT, AST bình thường, tiểu cầu 222, lách không lớn, FIB-4 khoảng 0.62. Nếu không có xơ gan ở nam 35 tuổi thì nghĩ tới viêm gan B không xơ, u tuyến gan ác tính hoá, ung thư biểu mô tế bào gan thể xơ lá (fibrolamellar, AFP thường không tăng), hoặc u di căn tiết AFP. Cần yếu tố nào để chọn giữa các khả năng này?","d":0},{"k":"b","x":"**Vì sao AFP 705 mà PIVKA-II bình thường?** Hai chỉ điểm phản ánh hai cơ chế khác nhau; sự không đồng thuận này gợi ý gì về sinh học u và về khả năng nguồn AFP khác?","d":0},{"k":"b","x":"**Bệnh nhân còn trong tiêu chuẩn Milan không?** Siêu âm chỉ thấy 2 ổ nhỏ nhưng chẩn đoán ghi “đa ổ”: CT có bao nhiêu ổ, ổ lớn nhất bao nhiêu, có xâm lấn mạch không? TACE ở đây là bắc cầu hay hạ giai đoạn?","d":0},{"k":"b","x":"**Vì sao đổi sang cháo và tăng theo dõi sinh hiệu từ 29/09?** Có phải chuẩn bị TACE hay chỉ theo quy trình khoa? Mức độ đau hạ sườn phải hiện nay ra sao?","d":0},{"k":"b","x":"**Ghép gan theo hướng nào?** Người hiến sống hay tạng chết não, tương hợp ABO, và tiêu chuẩn của trung tâm ghép ở nơi bệnh nhân dự định điều trị.","d":0}],"Kiến thức cần nắm":[{"k":"b","x":"**Tiêu chuẩn Milan:** 1 ổ đường kính đến 5 cm, hoặc tối đa 3 ổ mỗi ổ đến 3 cm; không xâm lấn mạch, không di căn ngoài gan. Trong Milan, kết quả sau ghép tương đương ghép vì bệnh gan lành tính.","d":0},{"k":"b","x":"**Ngưỡng AFP trong chọn ghép gan (bẫy MCQ):** trên 400 ng/mL là chống chỉ định tương đối theo một số hướng dẫn; trên 1000 ng/mL là chống chỉ định tuyệt đối theo một số hướng dẫn; UNOS yêu cầu hạ AFP dưới 500 ng/mL mới cấp điểm ngoại lệ nếu ban đầu trên 1000. Cần đối chiếu hướng dẫn nơi ghép.","d":0},{"k":"b","x":"**BCLC 2022:** BCLC-B chia 3 nhóm theo gánh nặng u và chức năng gan; nhóm đủ tiêu chuẩn ghép mở rộng thì nghĩ tới ghép; TACE chỉ dành cho ổ đa ổ khu trú, chức năng gan còn tốt; hạ giai đoạn thành công bằng TACE hoặc TARE mở đường ghép.","d":0},{"k":"b","x":"**Chẩn đoán HCC bằng hình ảnh không sinh thiết chỉ áp dụng cho bệnh nhân nguy cơ cao** (xơ gan, viêm gan B mạn, tiền sử HCC): dễ nhầm khi bệnh nhân gan không xơ.","d":0},{"k":"b","x":"**Child-Pugh:** 5 tiêu chí gồm bilirubin, albumin, INR, cổ trướng, bệnh não gan; TACE thường dành cho Child-Pugh A đến B7.","d":0},{"k":"b","x":"**Chống chỉ định TACE (theo thực hành chung, cần đối chiếu):** suy gan nặng (Child-Pugh C), tắc tĩnh mạch cửa chính, suy thận nặng, bilirubin cao, không có đường vào động mạch.","d":0},{"k":"b","x":"**Hội chứng sau tắc mạch:** sốt, đau, buồn nôn, tăng men gan thoáng qua; nguy cơ suy gan sau TACE nếu chức năng gan kém.","d":0},{"k":"b","x":"**FIB-4 = tuổi x AST / (tiểu cầu x căn bậc hai ALT):** dưới 1.3 nguy cơ xơ hoá tiến triển thấp; là công cụ sàng lọc.","d":0},{"k":"b","x":"**PIVKA-II (DCP):** prothrombin thiếu carboxyl hoá, tăng ở HCC; có thể tăng giả khi dùng warfarin hoặc thiếu vitamin K.","d":0}],"Kiến thức cần đào sâu":[{"k":"b","x":"**Bắc cầu và hạ giai đoạn bằng TACE trước ghép gan:** tiêu chuẩn Milan, UCSF, các mô hình có AFP; cách đọc đáp ứng AFP và thời gian quan sát tối thiểu (khoảng 3 tháng) trước khi ghép; so sánh TACE, TARE và đốt u. Gợi ý nguồn: BCLC 2022 (J Hepatol), chính sách UNOS/OPTN về HCC, đồng thuận ILTS, thử nghiệm XXL về hạ giai đoạn (Mazzaferro, Lancet Oncol 2020, cần đối chiếu), UpToDate mục liver transplantation for HCC.","d":0},{"k":"b","x":"**HCC ở người trẻ không xơ gan:** dịch tễ viêm gan B, u tuyến gan ác hoá, thể xơ lá; cách tiếp cận chẩn đoán khi AFP cao và PIVKA-II thấp. Gợi ý nguồn: hướng dẫn EASL 2018 về HCC, Harrison mục ung thư gan.","d":0},{"k":"b","x":"**Sinh học và ứng dụng AFP, AFP-L3, PIVKA-II (điểm GALAD):** khi nào phối hợp chỉ điểm, ưu nhược từng chỉ điểm.","d":0}]}}],
    ["TH-002","Tiêu hoá (đi thêm)","2026-09-26",1,"3ebcb1425c8181e981bcd409265763c7","Đang nằm viện","111110",{"d":"Sỏi túi mật có viêm (K80.0), đã cắt túi mật nội soi 29/09; gan nhiễm mỡ độ II-III; men gan tăng trước mổ","c":[["Nguy cơ sỏi ống mật chủ ở bệnh nhân sỏi túi mật: phân tầng ASGE 2019 và chọn MRCP, EUS, chụp đường mật trong mổ","3ebcb1425c81819fb26cee69c3046270"]],"s":{"CLS":[{"k":"t","h":true,"r":[["Chỉ số","Tham chiếu","26/09","28/09"],["Creatinin (µmol/L)","Nam 62–106","85.6","–"],["Ure máu (mmol/L)","1.7–8.3","4.4","–"],["Glucose (mmol/L)","3.9–6.4","6.61","–"],["Natri (mmol/L)","135–145","137.0","–"],["Kali (mmol/L)","3.5–5.0","3.60","–"],["Chloride (mmol/L)","96–110","100.6","–"],["Amylase (U/L)","28–100","33.80","–"],["AST / SGOT (U/L)","26/09: Nam <37; 28/09: Nam 10–50","60.8","47.5"],["ALT / SGPT (U/L)","26/09: Nam <41; 28/09: Nam 10–50","156.4","125.5"],["Bilirubin toàn phần (µmol/L)","<17.1","26.7","–"],["Bilirubin trực tiếp (µmol/L)","<5.1","4.4","7.5"],["PT (giây)","10–13","–","12.0"],["INR","1–1.2","–","1.06"],["PT (%)",">70","–","92"],["Nhóm máu ABO, Rh(D)","–","–","A, Rh(D) dương"],["Bạch cầu WBC (G/L)","4–11","12.91","7.66"],["NEUT (%)","45–75","82.2","54.4"],["NEUT (G/L)","1.8–8.25","10.60","4.17"],["LYM (%)","20–40","13.2","35.1"],["LYM (G/L)","0.8–4.4","1.71","2.69"],["MONO (%)","4–10","3.6","6.7"],["MONO (G/L)","0.16–1.1","0.47","0.51"],["EOS (%)","2–8","0.6","3.0"],["EOS (G/L)","0.08–0.88","0.08","0.23"],["BASO (%)","0–2","0.4","0.8"],["BASO (G/L)","0–0.22","0.05","0.06"],["Hồng cầu RBC (T/L)","3.8–5.5","5.48","5.37"],["Hemoglobin (g/L)","120–170","155","154"],["Hematocrit (%)","34–50","45.6","45.4"],["MCV (fL)","78–100","83.2","84.5"],["MCH (pg)","24–33","28.3","28.7"],["MCHC (g/L)","315–355","340","339"],["RDW-CV (%)","11–16","11.7","12.0"],["RDW-SD (fL)","37–54","35.3","36.5"],["Tiểu cầu PLT (G/L)","150–450","253","252"],["MPV (fL)","7.0–12","10.5","10.5"],["PCT (%)","0.1–0.5","0.26","0.26"]]},{"k":"p","x":"Màu: xanh = thấp hơn tham chiếu, đỏ = cao hơn, đen = bình thường.","d":0},{"k":"p","x":"**Ghi chú về bảng:**","d":0},{"k":"b","x":"Tham chiếu lấy từ cột “Phạm vi” trên phần mềm xét nghiệm trong ảnh Minh gửi. AST và ALT được lab đổi khoảng giữa hai lần (26/09: Nam <37 và <41; 28/09: Nam 10–50); mỗi ô tô màu theo khoảng của đúng lần đó.","d":0},{"k":"b","x":"Đơn vị của các chỉ số công thức máu và PCT không hiện trong ảnh, ghi theo đơn vị thường dùng.","d":0},{"k":"b","x":"Xét nghiệm 26/09 lấy lúc 18:46 (vào viện); xét nghiệm 28/09 lấy lúc 08:37.","d":0},{"k":"p","x":"**Chẩn đoán hình ảnh:**","d":0},{"k":"b","x":"**Siêu âm ổ bụng 26/09/2026 (thực hiện 19:19, trả kết quả 19:21):**","d":0},{"k":"b","x":"Gan: không lớn, bờ đều, đồng nhất, tăng âm, không có tổn thương khu trú.","d":1},{"k":"b","x":"Mật: túi mật có sỏi và bùn, sỏi khoảng 15 mm; túi mật kích thước khoảng 103×31 mm, thành dày khoảng 3 mm. Đường mật không sỏi, không dãn.","d":1},{"k":"b","x":"Lách không lớn, đồng dạng. Tụy bình thường. Hai thận không sỏi, không ứ nước, chủ mô bình thường. Bàng quang thành không dày, không cặn lắng, không sỏi. Màng phổi không dịch. Dịch ổ bụng (-).","d":1},{"k":"b","x":"Kết luận: sỏi + bùn / dãn + dày thành túi mật (theo dõi viêm túi mật); gan mỡ độ II.","d":1},{"k":"b","x":"**Siêu âm ổ bụng 28/09/2026 (thực hiện 15:30, trả kết quả 15:32):**","d":0},{"k":"b","x":"Gan: không lớn, bờ đều, tăng âm đồng nhất, không có tổn thương khu trú.","d":1},{"k":"b","x":"Mật: túi mật có sỏi bùn khoảng 6 mm, không dãn, thành không dày. Đường mật không sỏi, không dãn.","d":1},{"k":"b","x":"Lách, tụy, hai thận, bàng quang bình thường. Màng phổi không dịch. Dịch ổ bụng (-).","d":1},{"k":"b","x":"Kết luận: gan nhiễm mỡ độ II–III; sỏi bùn túi mật.","d":1},{"k":"b","x":"**Nhận xét dữ kiện:** hai lần siêu âm cách nhau 2 ngày, khác máy và khác người đọc; mô tả túi mật khác nhau rõ (26/09 dãn + dày thành; 28/09 không dãn, thành không dày).","d":0},{"k":"p","x":"**CLS đã chỉ định nhưng chưa thấy kết quả trong ảnh:**","d":0},{"k":"b","x":"Y lệnh 28/09 ghi 11 mục cận lâm sàng; ảnh chỉ có kết quả 6 mục (PT/INR, nhóm máu, bilirubin trực tiếp, ALT, AST, công thức máu). Các mục ở đầu danh sách bị cuộn khỏi khung ảnh.","d":0},{"k":"b","x":"Chưa thấy xét nghiệm nào sau mổ (29/09 đến nay).","d":0}],"Điều trị":[{"k":"p","x":"**26/09 (21:15):**","d":0},{"k":"b","x":"Clindamycin (Clindamycin-Hameln 150 mg/mL, hàm lượng ghi 600 mg): 1 ống, tiêm truyền tĩnh mạch (tốc độ truyền không đọc rõ trong ảnh)","d":0},{"k":"b","x":"Natri clorid 0,9% (100 mL): 1 chai, pha thuốc","d":0},{"k":"p","x":"**27/09 (07:00):**","d":0},{"k":"b","x":"Clindamycin 600 mg: số lượng 2 ống","d":0},{"k":"b","x":"Natri clorid 0,9%: số lượng 2 chai","d":0},{"k":"p","x":"**28/09 (08:32), ghi “thêm kháng sinh điều trị”:**","d":0},{"k":"b","x":"Tenafotin 2000: số lượng 2 lọ","d":0},{"k":"b","x":"Rabeloc I.V: số lượng 2 lọ","d":0},{"k":"b","x":"Natri clorid 0,9%: số lượng 2 chai","d":0},{"k":"b","x":"Nước cất pha tiêm 5 mL: số lượng 2 ống","d":0},{"k":"b","x":"Partamol tab: số lượng 2 viên","d":0},{"k":"b","x":"Clindamycin không thấy trong y lệnh 28/09 (có thể đã thay bằng Tenafotin hoặc dòng thuốc bị cuộn khỏi ảnh; cần đối chiếu)","d":0},{"k":"p","x":"**29/09 (13:30), phòng mổ:**","d":0},{"k":"b","x":"Bridion: 1 lọ","d":0},{"k":"p","x":"**29/09 (14:36), sau mổ chuyển hồi tỉnh:**","d":0},{"k":"b","x":"Glucose 10%: 1 chai","d":0},{"k":"b","x":"Natri clorid 0,9%: 1 chai","d":0},{"k":"b","x":"Tenafotin 2000: 1 lọ","d":0},{"k":"b","x":"Ofloxacin 200 mg/40 mL: 1 lọ","d":0},{"k":"b","x":"Rabeloc I.V: 1 lọ","d":0},{"k":"b","x":"Nước cất pha tiêm 5 mL: 1 ống","d":0},{"k":"b","x":"Paracetamol 500 mg/50 mL: 1 lọ","d":0},{"k":"p","x":"**29/09 (16:43), hồi tỉnh:**","d":0},{"k":"b","x":"Thở oxy: 3 giờ","d":0},{"k":"b","x":"Paracetamol 500 mg/50 mL: 1 lọ","d":0},{"k":"b","x":"Acupan: 1 ống","d":0},{"k":"p","x":"**29/09 (21:00):**","d":0},{"k":"b","x":"Natri clorid 0,9%: 1 chai (đã cấp phát)","d":0},{"k":"p","x":"**30/09 (08:09):**","d":0},{"k":"b","x":"Ofloxacin 200 mg/40 mL: số lượng 2 lọ","d":0},{"k":"b","x":"Tenafotin 2000: số lượng 2 lọ","d":0},{"k":"b","x":"Natri clorid 0,9%: số lượng 2 chai (đã cấp phát)","d":0},{"k":"b","x":"Rabeloc I.V: số lượng 2 lọ","d":0},{"k":"b","x":"Nước cất pha tiêm 5 mL: số lượng 2 ống","d":0},{"k":"b","x":"Partamol tab: số lượng 2 viên","d":0},{"k":"p","x":"**01/10 (08:10), y lệnh lập sẵn:**","d":0},{"k":"b","x":"Ofloxacin 200 mg/40 mL: số lượng 2 lọ","d":0},{"k":"b","x":"Tenafotin 2000: số lượng 2 lọ","d":0},{"k":"b","x":"Natri clorid 0,9%: số lượng 2 chai","d":0},{"k":"b","x":"Rabeloc I.V: số lượng 2 lọ","d":0},{"k":"b","x":"Nước cất pha tiêm 5 mL: số lượng 2 ống","d":0},{"k":"b","x":"Partamol tab: số lượng 2 viên","d":0},{"k":"p","x":"**Y lệnh chăm sóc và theo dõi:**","d":0},{"k":"b","x":"Theo dõi mạch, nhiệt, huyết áp: 8 giờ/lần (26/09 đến 28/09); 1 giờ/lần lúc hồi tỉnh (29/09 14:36); 3 giờ/lần (16:43); 4 giờ/lần (21:00); trở lại 8 giờ/lần từ 30/09","d":0},{"k":"b","x":"Chăm sóc: cấp hai (26 và 27/09), cấp ba (28/09), cấp hai rồi cấp một sau mổ (29/09), cấp ba từ 30/09","d":0},{"k":"b","x":"Dinh dưỡng: BT01-Cháo (26 và 27/09), BT02-Cháo (28/09), NAN01-Nhịn và TNH01-Tạm nhịn (29/09), BT02-Cháo từ 30/09","d":0}],"Phân tích đề nghị CLS (AI)":[{"k":"p","x":"**Dữ kiện của ca và ý nghĩa**","d":0},{"k":"b","x":"**Siêu âm 26/09 (sỏi + bùn, túi mật dãn 103×31 mm, thành dày khoảng 3 mm) cộng WBC 12.91 với neutrophil 82%:** gợi ý viêm túi mật cấp. Theo Tokyo Guidelines 2018 (TG18), chẩn đoán xác định cần 1 dấu hiệu viêm tại chỗ (dấu Murphy, đau hoặc khối vùng hạ sườn phải) cộng 1 dấu hiệu viêm toàn thân (sốt, CRP tăng, bạch cầu tăng) cộng hình ảnh phù hợp. Ca này có bạch cầu tăng, hình ảnh gợi ý, đau thượng vị rồi hạ sườn phải; chưa thấy dấu Murphy, nhiệt độ và CRP trong ảnh nên chưa khẳng định được mức chẩn đoán (cần đối chiếu).","d":0},{"k":"b","x":"**Bạch cầu về bình thường sau 2 ngày kháng sinh (12.91 xuống 7.66):** phù hợp đáp ứng điều trị hoặc cơn viêm nhẹ; Hb 154 và tiểu cầu 252 bình thường.","d":0},{"k":"b","x":"**Men gan và bilirubin lúc vào viện:** ALT 156.4 (cao hơn 3 lần giới hạn trên), AST 60.8, bilirubin toàn phần 26.7 µmol/L (khoảng 1.56 mg/dL), bilirubin trực tiếp 4.4 (chưa tăng). Bilirubin tăng chủ yếu phần gián tiếp (khoảng 22 µmol/L), không phải kiểu ứ mật điển hình. Suy luận của AI: cần phân biệt tổn thương tế bào gan (gan nhiễm mỡ độ II–III, viêm quanh túi mật lan vào gan), sỏi đi qua ống mật chủ, hoặc bilirubin gián tiếp tăng đơn thuần (ví dụ Gilbert); ALP và GGT chưa có nên chưa xác định được.","d":0},{"k":"b","x":"**Diễn tiến 28/09:** ALT giảm còn 125.5, AST về 47.5 (theo khoảng 10–50 của lần này), nhưng bilirubin trực tiếp tăng từ 4.4 lên 7.5 (trên giới hạn <5.1). Đây là điểm cần theo dõi vì thay đổi theo hướng ứ mật nhẹ.","d":0},{"k":"b","x":"**Amylase 33.8 (bình thường):** không ủng hộ viêm tụy cấp do sỏi.","d":0},{"k":"b","x":"**Phân tầng nguy cơ sỏi ống mật chủ (ASGE 2019, theo hiểu biết của AI, cần đối chiếu):** không có sỏi ống mật chủ trên hình ảnh, không viêm đường mật, ống mật chủ không dãn, bilirubin toàn phần dưới 4 mg/dL (khoảng 68 µmol/L); có men gan bất thường nên xếp nguy cơ trung gian. Nhóm này thường cần thêm một bước xác nhận (siêu âm nội soi, MRCP, hoặc chụp đường mật trong mổ) trước hoặc trong lúc cắt túi mật.","d":0},{"k":"b","x":"**PT 12.0, INR 1.06, PT 92% (28/09):** đông máu bình thường trước mổ. Nhóm máu A, Rh(D) dương.","d":0},{"k":"b","x":"**Glucose 6.61 mmol/L lúc vào viện:** cao nhẹ, chưa rõ đói hay không; có thể do stress cấp. Gan nhiễm mỡ độ II–III ở người 26 tuổi nên đáng làm thêm đường huyết đói.","d":0},{"k":"b","x":"**Hai lần siêu âm mô tả túi mật khác nhau (dãn và dày thành rồi không dãn, thành không dày sau 2 ngày):** có thể là cải thiện thật hoặc khác biệt máy, người đọc và thời điểm; không thay đổi chỉ định mổ vì vẫn còn sỏi bùn có triệu chứng, nhưng nên đối chiếu với mô tả trong mổ và giải phẫu bệnh.","d":0},{"k":"p","x":"**CLS còn thiếu, nên cân nhắc (kèm điều kiện)**","d":0},{"k":"b","x":"**AST, ALT, bilirubin toàn phần và trực tiếp, ALP, GGT sau mổ:** chỉ định nên làm sớm (trong 1 đến 2 ngày tới, trước ra viện), vì bilirubin trực tiếp đang tăng và ALT chưa về bình thường trước mổ; nếu không giảm thì nghĩ tới sỏi sót ống mật chủ, rò mật hoặc tổn thương đường mật.","d":0},{"k":"b","x":"**Chụp đường mật trong mổ hoặc MRCP:** nếu ca mổ chưa chụp đường mật trong mổ và men gan hoặc bilirubin không về bình thường sau mổ, MRCP là bước tiếp theo ít xâm lấn nhất (cần đối chiếu tường trình phẫu thuật).","d":0},{"k":"b","x":"**CRP (± procalcitonin):** thuộc tiêu chuẩn viêm toàn thân của TG18 và giúp quyết định thời gian kháng sinh; ảnh chưa thấy.","d":0},{"k":"b","x":"**Cấy máu:** TG18 khuyến cáo khi viêm túi mật độ II–III hoặc sốt cao; độ I có thể không cần. Chỉ định khi có sốt hoặc dấu hiệu nhiễm khuẩn huyết.","d":0},{"k":"b","x":"**Giải phẫu bệnh túi mật sau mổ:** nên gửi thường quy (loại trừ tổn thương ác tính hiếm gặp, đánh giá mức độ viêm).","d":0},{"k":"b","x":"**Đường huyết đói và HbA1c, mỡ máu:** vì gan nhiễm mỡ độ II–III và glucose 6.61.","d":0},{"k":"b","x":"**HBsAg, anti-HCV:** nếu ALT vẫn cao sau mổ và ổn định, cần tìm nguyên nhân gan khác ngoài túi mật và gan nhiễm mỡ.","d":0},{"k":"b","x":"**FIB-4 (tham khảo):** khoảng 0.50 ở 26/09 (tuổi 26, AST 60.8, tiểu cầu 253, ALT 156.4) và khoảng 0.44 ở 28/09, đều dưới 1.3. Khi men gan còn dao động do bệnh túi mật cấp, FIB-4 kém tin cậy; nên tính lại khi men gan ổn định.","d":0},{"k":"p","x":"**CLS chưa cần, hoặc nên tránh làm thừa**","d":0},{"k":"b","x":"Không cần lặp siêu âm ổ bụng thường quy nếu lâm sàng hậu phẫu ổn; chỉ lặp khi đau tăng, sốt, vàng da hoặc nghi tụ dịch dưới gan.","d":0},{"k":"b","x":"Không cần lặp amylase khi không đau kiểu tụy.","d":0},{"k":"b","x":"Không cần CT ổ bụng nếu không có biến chứng nghi ngờ (áp xe, rò mật).","d":0}],"Phân tích điều trị (AI)":[{"k":"p","x":"**1. Cắt túi mật nội soi (29/09)**","d":0},{"k":"b","x":"**Cơ chế:** loại bỏ nguồn gây bệnh (túi mật có sỏi) nên là điều trị triệt để; kháng sinh chỉ kiểm soát nhiễm khuẩn tạm thời, không ngăn tái phát.","d":0},{"k":"b","x":"**Thời điểm:** TG18 khuyến cáo cắt túi mật nội soi sớm cho viêm túi mật cấp độ I và II tại trung tâm có kinh nghiệm. Mổ ngày thứ 4 kể từ nhập viện (26/09 đến 29/09) phù hợp xu hướng mổ sớm, và cần đối chiếu WSES 2020 về khung thời gian từ lúc khởi phát (không có ngày khởi phát trong ảnh).","d":0},{"k":"b","x":"**Gây mê:** Bridion là sugammadex (theo hiểu biết của AI, cần đối chiếu nhãn), dùng đảo ngược giãn cơ nhóm rocuronium hoặc vecuronium khi kết thúc mổ. Sau mổ theo dõi nhịp chậm và dị ứng hiếm gặp.","d":0},{"k":"b","x":"**Theo dõi sau mổ:** vết mổ thấm dịch máu ít, huyết động ổn (bình thường sớm sau mổ). Cần để ý: đau hạ sườn phải tăng, sốt, vàng da, dịch mật qua dẫn lưu nếu có (rò mật); bilirubin và men gan tăng lại (sỏi sót ống mật chủ, tổn thương đường mật); chảy máu.","d":0},{"k":"b","x":"**Điểm cần đối chiếu:** y lệnh 30/09 và 01/10 vẫn ghi “đau hạ sườn phải, siêu âm viêm túi mật do sỏi”, giống y lệnh 28/09. Nên hỏi lại tình trạng đau hiện tại và cập nhật lại để y lệnh phản ánh hậu phẫu.","d":0},{"k":"p","x":"**2. Kháng sinh (Clindamycin, Tenafotin, Ofloxacin)**","d":0},{"k":"b","x":"**Diễn tiến thuốc trong ảnh:** 26 đến 27/09 clindamycin; từ 28/09 Tenafotin 2000; từ 29/09 (sau mổ) thêm ofloxacin; 30/09 và 01/10 vẫn Tenafotin + ofloxacin.","d":0},{"k":"b","x":"**Cơ chế phổ:** vi khuẩn thường gặp trong viêm túi mật là trực khuẩn Gram âm đường ruột (E. coli, Klebsiella), có thể có Enterococcus và vi khuẩn kỵ khí. Clindamycin phủ Gram dương và kỵ khí nhưng không phủ Gram âm đường ruột nên không phù hợp làm thuốc duy nhất cho viêm túi mật; chuyển sang thuốc phủ Gram âm là hợp lý. Tenafotin 2000 theo hiểu biết của AI là cefoxitin 2 g (cephamycin, phủ Gram âm đường ruột và nhiều kỵ khí); cần đối chiếu nhãn thuốc thực tế.","d":0},{"k":"b","x":"**Ofloxacin thêm sau mổ:** chồng lấp phổ Gram âm với cefoxitin, chưa thấy chỉ định rõ trong ảnh (không thấy bằng chứng nhiễm khuẩn ngoài túi mật). Fluoroquinolone cần cân nhắc: kéo dài QT, viêm gân, rối loạn đường huyết (bệnh nhân có glucose 6.61), và hạn chế dùng khi có lựa chọn khác.","d":0},{"k":"b","x":"**Thời gian dùng (TG18 antimicrobial 2018, cần đối chiếu):** viêm túi mật độ I, sau khi cắt túi mật và nguồn nhiễm được kiểm soát hoàn toàn thì ngừng kháng sinh trong khoảng 24 giờ sau mổ; độ II–III dùng khoảng 4 đến 7 ngày sau kiểm soát nguồn (dài hơn nếu có nhiễm khuẩn huyết vi khuẩn Gram dương như Enterococcus, Streptococcus). Ca này đã có kháng sinh từ 26/09, y lệnh lập sẵn đến 01/10 (sau mổ 2 ngày).","d":0},{"k":"b","x":"**Khuyến nghị thực hành (để Minh cân nhắc):** xác định độ nặng TG18 và phát hiện trong mổ (túi mật hoại tử, thủng, mủ, tụ dịch quanh túi mật) rồi thống nhất ngày dừng kháng sinh với bác sĩ điều trị; hỏi lý do dùng hai kháng sinh song song sau mổ.","d":0},{"k":"p","x":"**3. Ức chế bơm proton (Rabeloc I.V)**","d":0},{"k":"b","x":"**Cơ chế:** ức chế H+/K+-ATPase tế bào thành dạ dày, giảm tiết acid. Theo hiểu biết của AI, Rabeloc I.V là rabeprazole tiêm tĩnh mạch; cần đối chiếu nhãn.","d":0},{"k":"b","x":"**Nhận xét:** chẩn đoán “viêm dạ dày” chưa có nội soi trong ảnh. PPI tĩnh mạch chủ yếu dành cho lúc không uống được hoặc xuất huyết tiêu hoá; bệnh nhân đã ăn cháo từ 30/09 nên có thể cân nhắc chuyển đường uống. Cần đối chiếu chỉ định; nếu triệu chứng thượng vị kéo dài sau mổ thì cân nhắc nội soi dạ dày (kèm tìm Helicobacter pylori).","d":0},{"k":"p","x":"**4. Giảm đau (Paracetamol, Acupan, Partamol)**","d":0},{"k":"b","x":"**Cơ chế:** giảm đau đa mô thức: paracetamol nền cộng nefopam (Acupan, theo hiểu biết của AI, là thuốc giảm đau không opioid tác dụng trung ương) giúp giảm nhu cầu opioid sau cắt túi mật nội soi.","d":0},{"k":"b","x":"**Lưu ý:** paracetamol nên giữ tổng liều trong giới hạn an toàn (Partamol 2 viên mỗi ngày tương đương khoảng 1 g); ALT tăng 125 đến 156 U/L ở mức nhẹ, không phải chống chỉ định nhưng nên theo dõi. Nefopam có thể gây buồn nôn, vã mồ hôi, nhịp nhanh, bí tiểu; thận trọng khi có tiền sử co giật.","d":0},{"k":"p","x":"**5. Dịch và dinh dưỡng**","d":0},{"k":"b","x":"Sau mổ dùng Glucose 10% và Natri clorid 0,9%, nhịn rồi chuyển cháo từ 30/09: hợp với hướng ăn lại sớm sau cắt túi mật nội soi không biến chứng.","d":0},{"k":"b","x":"Trước ra viện: nên có men gan và bilirubin sau mổ, kết quả giải phẫu bệnh (hoặc hẹn lấy), hướng dẫn ăn giảm mỡ và kiểm soát gan nhiễm mỡ độ II–III.","d":0},{"k":"p","x":"**Nguồn tham khảo (tôi chỉ đọc được tiêu đề khi tra cứu; số liệu ghi theo hiểu biết của AI, cần đối chiếu bản gốc):**","d":0},{"k":"b","x":"Tokyo Guidelines 2018: antimicrobial therapy for acute cholangitis and cholecystitis, J Hepatobiliary Pancreat Sci","d":0},{"k":"b","x":"Tokyo Guidelines 2018: antimicrobial therapy, PubMed","d":0},{"k":"b","x":"ASGE guideline on the role of endoscopy in the evaluation and management of choledocholithiasis, 2019","d":0}],"Thắc mắc lâm sàng":[{"k":"b","x":"**Độ nặng theo TG18 là gì?** Có dấu Murphy, sốt, CRP? WBC 12.91 chưa đến ngưỡng 18 của độ II; điều gì trong mô tả lúc mổ (hoại tử, thủng, mủ) sẽ đổi độ và đổi thời gian kháng sinh?","d":0},{"k":"b","x":"**Vì sao ALT 156.4 và bilirubin toàn phần 26.7 (chủ yếu gián tiếp) ở nam 26 tuổi?** Do gan nhiễm mỡ độ II–III, viêm túi mật lan vào gan, sỏi đi qua ống mật chủ, hay Gilbert? Cần ALP, GGT và men gan sau mổ để chọn.","d":0},{"k":"b","x":"**Nguy cơ sỏi ống mật chủ trung gian (ASGE 2019): đã chụp đường mật trong mổ hoặc MRCP chưa?** Nếu chưa, theo dõi sau mổ và ngưỡng làm MRCP ở ca này là gì, nhất là khi bilirubin trực tiếp tăng từ 4.4 lên 7.5?","d":0},{"k":"b","x":"**Vì sao chuyển từ clindamycin sang Tenafotin rồi thêm ofloxacin sau mổ?** Kết quả mổ có đủ cơ sở kéo dài hai kháng sinh đến 01/10 hay có thể dừng sớm theo TG18?","d":0},{"k":"b","x":"**Chẩn đoán “viêm dạ dày” dựa trên gì?** Nội soi hay chỉ triệu chứng? PPI tĩnh mạch còn cần khi đã ăn cháo không?","d":0},{"k":"b","x":"**Hai lần siêu âm khác nhau nhiều trong 2 ngày:** thật sự cải thiện hay khác biệt kỹ thuật, và ảnh hưởng gì tới quyết định mổ?","d":0},{"k":"b","x":"**Gan nhiễm mỡ độ II–III ở 26 tuổi:** nguyên nhân chuyển hoá (đường huyết, mỡ máu, BMI, rượu) và kế hoạch theo dõi sau ra viện là gì?","d":0}],"Kiến thức cần nắm":[{"k":"b","x":"**Chẩn đoán viêm túi mật cấp theo TG18:** A (dấu Murphy, đau hoặc khối hạ sườn phải) + B (sốt, CRP tăng, bạch cầu tăng) + C (hình ảnh) = chẩn đoán xác định; nghi ngờ khi có 1 dấu A cộng 1 dấu B hoặc C.","d":0},{"k":"b","x":"**Phân độ TG18 (cần đối chiếu):** độ III có rối loạn chức năng cơ quan (tim mạch cần vận mạch, giảm ý thức, PaO2/FiO2 dưới 300, thiểu niệu hoặc creatinin trên 2.0, INR trên 1.5, tiểu cầu dưới 100 G/L); độ II khi bạch cầu trên 18 G/L, khối sờ thấy vùng hạ sườn phải, triệu chứng trên 72 giờ hoặc viêm khu trú rõ (hoại thư, áp xe, thủng, viêm túi mật tràn khí); độ I là còn lại.","d":0},{"k":"b","x":"**Xử trí theo độ (TG18):** độ I và II cắt túi mật nội soi sớm; độ III hồi sức và dẫn lưu túi mật qua da nếu không mổ được.","d":0},{"k":"b","x":"**Kháng sinh:** sau cắt túi mật độ I ngừng trong khoảng 24 giờ nếu nguồn nhiễm đã lấy hết; độ II–III khoảng 4 đến 7 ngày sau kiểm soát nguồn (cần đối chiếu TG18 antimicrobial 2018).","d":0},{"k":"b","x":"**Nguy cơ sỏi ống mật chủ (ASGE 2019, cần đối chiếu):** cao khi thấy sỏi ống mật chủ trên hình ảnh, viêm đường mật cấp, hoặc bilirubin toàn phần trên 4 mg/dL (khoảng 68 µmol/L) kèm ống mật chủ giãn (làm ERCP); trung gian khi men gan bất thường, tuổi trên 55, hoặc ống mật chủ giãn trên hình ảnh (làm EUS, MRCP hoặc chụp đường mật trong mổ); thấp khi không có yếu tố nào (cắt túi mật thẳng).","d":0},{"k":"b","x":"**Bẫy MCQ:** men gan tăng nhẹ đến vừa và bilirubin tăng nhẹ có thể gặp trong viêm túi mật đơn thuần, không tự động là sỏi ống mật chủ; amylase bình thường loại trừ tương đối viêm tụy do sỏi.","d":0},{"k":"b","x":"**Biến chứng cắt túi mật nội soi:** rò mật, tổn thương đường mật, chảy máu, sỏi sót ống mật chủ, tụ dịch dưới gan.","d":0},{"k":"b","x":"**Sugammadex (Bridion):** đảo ngược giãn cơ nhóm rocuronium/vecuronium; **nefopam (Acupan):** giảm đau không opioid, thận trọng khi co giật, bí tiểu, glaucoma góc đóng.","d":0}],"Kiến thức cần đào sâu":[{"k":"b","x":"**Phân tầng nguy cơ sỏi ống mật chủ ở bệnh nhân sỏi túi mật:** ASGE 2019 so với ESGE 2019, khi nào chọn EUS, MRCP, chụp đường mật trong mổ hay ERCP, và ý nghĩa của hướng thay đổi men gan theo thời gian. Gợi ý nguồn: ASGE guideline 2019 (Gastrointest Endosc), ESGE guideline 2019 (Endoscopy), UpToDate mục choledocholithiasis.","d":0},{"k":"b","x":"**Thời gian kháng sinh trong viêm túi mật cấp sau cắt túi mật:** TG18 antimicrobial (Gomi, 2018) và thử nghiệm Regimbeau (JAMA 2014, cần đối chiếu) về kháng sinh sau mổ ở viêm túi mật nhẹ đến vừa.","d":0},{"k":"b","x":"**Gan nhiễm mỡ ở người trẻ và đánh giá xơ hoá:** hạn chế của FIB-4 khi men gan đang dao động; khi nào đo đàn hồi gan. Gợi ý nguồn: hướng dẫn EASL-EASD-EASO về bệnh gan nhiễm mỡ liên quan rối loạn chuyển hoá.","d":0}]}}]
  ]
};
